// Browser-safe contracts for the Designer registry plugin.
export * from './shared/appManifest.ts';
export * from './shared/fileFormats.ts';
export * from './shared/fileOutputs.ts';
export * from './shared/guardrails.ts';
export * from './shared/htmlOutputs.ts';
export * from './shared/multiselect.ts';
export * from './shared/publishedRunner.ts';
export * from './shared/resultPreview.ts';
export * from './shared/storageConfig.ts';
export * from './shared/values.ts';

import { Plugin, ServiceContext, defineManifest, toPlugin, type IAppRouter } from '@databricks/appkit';
import manifest from './manifest.json';
import { createDesignerRuntime } from './server/runtime';
import type { WorkspaceClient } from './server/workspaceClient';

class DesignerPlugin extends Plugin {
  static manifest = defineManifest<'designer'>(manifest);
  private runtime?: ReturnType<typeof createDesignerRuntime>;

  setup() {
    // Designer Jobs and files are App-owned. Forwarded identity is checked by
    // each route; it must not switch these operations to a viewer's credentials.
    this.runtime = createDesignerRuntime(ServiceContext.get().client as WorkspaceClient, this.telemetry);
    return Promise.resolve();
  }

  injectRoutes(router: IAppRouter) {
    this.runtime?.registerRoutes(router, (config) => this.route(router, config));
  }

  shutdown() {
    this.runtime?.close();
    this.runtime = undefined;
  }
}

/** Published Lakeflow Designer App runtime (beta). */
export const designer = toPlugin(DesignerPlugin);

{
  "$schema": "https://databricks.github.io/appkit/schemas/plugin-manifest.schema.json",
  "name": "designer",
  "displayName": "Lakeflow Designer",
  "stability": "beta",
  "description": "Serve published Lakeflow Designer Apps with viewer-scoped runs, results, and file transfers.",
  "resources": {
    "required": [],
    "optional": [
      {
        "type": "job",
        "alias": "Designer runner",
        "resourceKey": "job",
        "description": "Publisher-owned Designer runner Job",
        "permission": "CAN_MANAGE",
        "fields": {
          "id": {
            "env": "DATABRICKS_JOB_ID",
            "description": "Job bound by the Designer publisher"
          }
        }
      }
    ]
  }
}

interface BrowserRequestOrigin {
  origin?: string;
  appUrl?: string;
  fetchSite?: string;
}

// CORS protects response reads, not side effects. HTML frames must not act through
// the viewer's App session, including when an App endpoint accepts an empty body.
export function isSameOriginBrowserRequest({ origin, appUrl, fetchSite }: BrowserRequestOrigin): boolean {
  if (fetchSite !== undefined && fetchSite !== 'same-origin' && fetchSite !== 'none') return false;
  // Non-browser API clients do not send browser origin metadata; ingress authenticates them.
  if (origin === undefined) return true;
  if (origin === 'null' || appUrl === undefined) return false;
  try {
    const url = new URL(origin);
    return (
      (url.protocol === 'http:' || url.protocol === 'https:') &&
      url.origin === origin &&
      url.origin === new URL(appUrl).origin
    );
  } catch {
    return false;
  }
}

import {
  FILE_OUTPUTS_MIME_TYPE,
  MAX_OUTPUT_FILES,
  parseFileOutputBehavior,
  type WrittenFiles,
} from '../shared/fileOutputs';
import type { GuardrailDiagnostic } from '../shared/guardrails';
import { isHtmlOutput } from '../shared/htmlOutputs';
import { DISPLAY_ROW_LIMIT, summarizeResultPreview } from '../shared/resultPreview';
import { isRecord } from '../shared/values';
import { commandGuardrailDiagnostics, mergeGuardrailDiagnostics } from './guardrails';

const RUNNER_PAYLOAD_VERSION = 2;
const NOTEBOOK_MODEL_ASSIGNMENT = /__DATABRICKS_NOTEBOOK_MODEL = '([^']*)'/;
const ROW_COUNTS_MIME_TYPE = 'application/vnd.databricks.lakeflow-designer.row-counts+json';
const RUNTIME_NODE_STATE_MIME_TYPE = 'application/vnd.databricks.lakebuilder.runtime-node-state+json';
// Each cell's display(ctx["<node>.<port>"]) lines name the ports it renders, in source order.
const DISPLAY_CTX_KEY = /display\(ctx\["([^"]+)"\]\)/g;

export function findNotebookModelValue(exportedHtml: unknown): string | undefined {
  if (typeof exportedHtml !== 'string') {
    return undefined;
  }
  const direct = exportedHtml.match(NOTEBOOK_MODEL_ASSIGNMENT);
  if (direct !== null) {
    return direct[1];
  }
  try {
    return Buffer.from(exportedHtml, 'base64').toString().match(NOTEBOOK_MODEL_ASSIGNMENT)?.[1];
  } catch {
    return undefined;
  }
}

function decodeNotebookModel(exportedHtml: unknown): Record<string, unknown> | undefined {
  const value = findNotebookModelValue(exportedHtml);
  if (value === undefined) {
    return undefined;
  }
  try {
    const parsed: unknown = JSON.parse(decodeURIComponent(Buffer.from(value, 'base64').toString()));
    return isRecord(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

function displayedCtxKeys(source: unknown): string[] {
  if (typeof source !== 'string') {
    return [];
  }
  return Array.from(source.matchAll(DISPLAY_CTX_KEY), (match) => match[1]);
}

// Node names carry no dots, so the last dot separates node and port.
function splitCtxKey(key: string): { node: string; port: string } {
  const dot = key.lastIndexOf('.');
  return dot === -1 ? { node: key, port: '' } : { node: key.slice(0, dot), port: key.slice(dot + 1) };
}

function simpleType(rawType: unknown): string {
  if (typeof rawType !== 'string') {
    return 'string';
  }
  try {
    const parsed: unknown = JSON.parse(rawType);
    return typeof parsed === 'string' ? parsed : rawType;
  } catch {
    return rawType;
  }
}

function toDisplayTable(entry: unknown) {
  if (!isRecord(entry) || entry.type !== 'table' || !Array.isArray(entry.schema) || !Array.isArray(entry.data)) {
    return undefined;
  }
  const schema = entry.schema.filter(isRecord).map((field) => ({
    name: typeof field.name === 'string' ? field.name : '',
    type: simpleType(field.type),
    nullable: typeof field.nullable === 'boolean' ? field.nullable : true,
  }));
  const columnNames = schema.map((field) => field.name);
  const data = entry.data.filter((row) => Array.isArray(row));
  const rows = data
    .slice(0, DISPLAY_ROW_LIMIT)
    .map((row) => Object.fromEntries(columnNames.map((name, index) => [name, row[index] ?? null])));
  // Notebook overflow does not distinguish row and byte limits or carry an exact total.
  // Preserve unknown overflow instead of interpreting absent metadata as a complete result.
  return {
    schema,
    rows,
    ...summarizeResultPreview(data.length, entry.overflow),
  };
}

function resultEntries(results: unknown): unknown[] {
  if (
    isRecord(results) &&
    (results.type === 'table' ||
      results.type === 'mimeBundle' ||
      results.type === 'htmlSandbox' ||
      results.type === 'html' ||
      results.type === 'ansi' ||
      results.type === 'text')
  )
    return [results];
  return isRecord(results) && Array.isArray(results.data) ? results.data : [];
}

// A MIME bundle may carry its payload as an object or a JSON string; unparseable strings are skipped.
function mimePayloads(results: unknown, mimeType: string): unknown[] {
  return resultEntries(results).flatMap((entry) => {
    if (!isRecord(entry) || entry.type !== 'mimeBundle' || !isRecord(entry.data)) return [];
    const payload = entry.data[mimeType];
    if (typeof payload !== 'string') return [payload];
    try {
      const parsed: unknown = JSON.parse(payload);
      return [parsed];
    } catch {
      return [];
    }
  });
}

const isPortCount = (entry: [string, unknown]): entry is [string, number] =>
  entry[0] !== '' && typeof entry[1] === 'number' && Number.isSafeInteger(entry[1]) && entry[1] >= 0;

function exactRowCounts(results: unknown): Map<string, number> {
  const counts = new Map<string, number>();
  for (const payload of mimePayloads(results, ROW_COUNTS_MIME_TYPE)) {
    if (!isRecord(payload) || typeof payload.node !== 'string' || payload.node === '' || !isRecord(payload.counts)) {
      continue;
    }
    // One invalid count discards the node's whole payload.
    const portCounts = Object.entries(payload.counts);
    if (portCounts.length === 0 || !portCounts.every(isPortCount)) {
      continue;
    }
    for (const [port, count] of portCounts) {
      counts.set(`${payload.node}\0${port}`, count);
    }
  }
  return counts;
}

function runtimeNodeStates(results: unknown): Map<string, { disabled: boolean }> {
  const states = new Map<string, { disabled: boolean }>();
  for (const payload of mimePayloads(results, RUNTIME_NODE_STATE_MIME_TYPE)) {
    if (
      isRecord(payload) &&
      typeof payload.nodeId === 'string' &&
      payload.nodeId !== '' &&
      typeof payload.disabled === 'boolean'
    ) {
      states.set(payload.nodeId, { disabled: payload.disabled });
    }
  }
  return states;
}

function writtenFiles(results: unknown): WrittenFiles[] {
  return mimePayloads(results, FILE_OUTPUTS_MIME_TYPE).flatMap((receipt) => {
    if (
      !isRecord(receipt) ||
      typeof receipt.node !== 'string' ||
      receipt.node === '' ||
      !Array.isArray(receipt.files) ||
      receipt.files.length > MAX_OUTPUT_FILES ||
      !receipt.files.every((file): file is { path: string } => isRecord(file) && typeof file.path === 'string')
    ) {
      return [];
    }
    const behavior = parseFileOutputBehavior(receipt.behavior);
    return [
      {
        node: receipt.node,
        files: receipt.files.map((file) => ({ path: file.path })),
        ...(behavior ? { behavior } : {}),
      },
    ];
  });
}

// Only runner-marked HTML cells can become App HTML blocks. Other rich displays stay private.
function htmlOutputs(source: unknown, results: unknown): Record<string, unknown>[] {
  if (typeof source !== 'string') return [];
  const markers = [...source.matchAll(/^# designer-app-html-output: (.+)$/gm)];
  if (markers.length !== 1) return [];
  let node: unknown;
  try {
    node = JSON.parse(markers[0][1]);
  } catch {
    return [];
  }
  if (typeof node !== 'string' || node === '') return [];
  const entries = resultEntries(results).flatMap((entry) => {
    if (!isRecord(entry)) return [];
    if (entry.type === 'mimeBundle' && isRecord(entry.data) && 'text/html' in entry.data) {
      return [entry.data['text/html']];
    }
    return entry.type === 'htmlSandbox' || entry.type === 'html' ? [entry.data] : [];
  });
  if (entries.length === 0) return [];
  const binding = { kind: 'html', target_node: node };
  if (entries.length !== 1 || !isHtmlOutput(entries[0])) {
    return [
      {
        ...binding,
        status: 'error',
        error: {
          type: 'HtmlOutputError',
          message:
            entries.length !== 1
              ? 'The HTML operator must display exactly one HTML page.'
              : 'The HTML output is invalid or exceeds the 4,194,304-character limit. Reduce the page size or its input data.',
        },
      },
    ];
  }
  return [{ ...binding, status: 'ok', html: entries[0] }];
}

// MIME metadata must not consume a table ordinal when pairing results with display calls.
export function exportedModelToRunPayload(exportedHtml: unknown, taskErrorTexts: string[] = []): string | undefined {
  const model = decodeNotebookModel(exportedHtml);
  if ((model === undefined || !Array.isArray(model.commands)) && taskErrorTexts.length === 0) {
    return undefined;
  }
  const outputs: Record<string, unknown>[] = [];
  const files: WrittenFiles[] = [];
  const diagnostics: GuardrailDiagnostic[] = [];
  const states = new Map<string, { disabled: boolean }>();
  const commands = Array.isArray(model?.commands) ? model.commands : [];
  for (const command of commands) {
    if (!isRecord(command)) {
      continue;
    }
    outputs.push(...htmlOutputs(command.command, command.results));
    diagnostics.push(...commandGuardrailDiagnostics(command, resultEntries(command.results)));
    const keys = displayedCtxKeys(command.command);
    for (const [nodeId, state] of runtimeNodeStates(command.results)) {
      states.set(nodeId, state);
    }
    // Receipts are independent of display results. A successful write must stay downloadable
    // even if the preview/count fails or this cell deliberately has no tabular preview.
    files.push(...writtenFiles(command.results));
    const rowCounts = exactRowCounts(command.results);
    const tables = resultEntries(command.results).flatMap((entry) => toDisplayTable(entry) ?? []);
    tables.forEach((table, index) => {
      const key = keys[index];
      if (key === undefined) {
        return;
      }
      const parts = splitCtxKey(key);
      const totalRowCount = rowCounts.get(`${parts.node}\0${parts.port}`);
      outputs.push({
        status: 'ok',
        target_node: parts.node,
        target_port: parts.port,
        ...table,
        ...(totalRowCount === undefined ? {} : { total_row_count: totalRowCount }),
      });
    });
  }
  return JSON.stringify({
    version: RUNNER_PAYLOAD_VERSION,
    outputs,
    files,
    diagnostics: mergeGuardrailDiagnostics(diagnostics, taskErrorTexts),
    ...(states.size > 0 ? { runtimeNodeStates: Object.fromEntries(states) } : {}),
  });
}

import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';

import type { IAppResponse as Response } from '@databricks/appkit/dist/shared/src/plugin';

export async function streamFileDownload(
  res: Response,
  stream: ReadableStream<Uint8Array>,
  filename: string,
  size: number,
  report: (error: unknown) => void
) {
  const fallback = filename.replace(/[^A-Za-z0-9._ -]/g, '_');
  const encoded = encodeURIComponent(filename).replace(
    /['()*]/g,
    (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`
  );
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader('Content-Disposition', `attachment; filename="${fallback}"; filename*=UTF-8''${encoded}`);
  res.setHeader('Content-Length', String(size));
  res.setHeader('X-Content-Type-Options', 'nosniff');
  const reader = stream.getReader();
  const cancelRead = () => {
    void reader.cancel().catch(report);
  };
  res.once('close', cancelRead);
  async function* bytes() {
    let transferred = 0;
    try {
      for (;;) {
        const next = await reader.read();
        if (next.done) break;
        transferred += next.value.byteLength;
        if (transferred > size) throw new Error('File changed during transfer.');
        yield next.value;
      }
      if (transferred !== size) throw new Error('File transfer was incomplete.');
    } finally {
      res.off('close', cancelRead);
      await reader.cancel().catch(report);
      reader.releaseLock();
    }
  }
  await pipeline(Readable.from(bytes()), res);
}

import { createHash, randomUUID } from 'node:crypto';

import {
  MAX_UPLOAD_SIZE_LABEL,
  UPLOAD_REFERENCE,
  UPLOAD_UNAVAILABLE,
  uploadStoragePath,
  type AppStorage,
} from '../shared/storageConfig';
import { isRecord } from '../shared/values';
import { runJobParameters } from './jobParameters';

export const APP_VIEWER_PARAM = '_lb_app_viewer';

export class UploadError extends Error {
  status: number;
  code?: typeof UPLOAD_UNAVAILABLE;
  constructor(status: number, message: string, options?: ErrorOptions & { code?: typeof UPLOAD_UNAVAILABLE }) {
    super(message, options);
    this.status = status;
    this.code = options?.code;
  }
}

const hash = (value: string) => createHash('sha256').update(value).digest('hex');

// Databricks Apps supplies this header at its authenticated ingress. Never take identity from a body/query.
export function viewerKey(forwardedUser: string | undefined, jobId: string | undefined): string | undefined {
  return forwardedUser?.trim() && jobId ? hash(JSON.stringify([jobId, forwardedUser.trim()])) : undefined;
}

export function canAccessRun(run: unknown, viewer: string | undefined): boolean {
  const owner = runJobParameters(run)[APP_VIEWER_PARAM];
  return viewer !== undefined && viewer !== '' && owner === viewer;
}

interface StoredUpload {
  reference: string;
  filename: string;
  size: number;
  createdAt: number;
}

// Keep storage operations behind a small boundary so failures/partial writes can be exercised without UC.
export interface UploadStore {
  mkdir(path: string): Promise<void>;
  put(path: string, bytes: Uint8Array): Promise<void>;
  putStream(path: string, stream: ReadableStream<Uint8Array>): Promise<void>;
  read(path: string): Promise<unknown>;
  download(path: string): Promise<ReadableStream<Uint8Array>>;
  size(path: string): Promise<number | undefined>;
  delete(path: string): Promise<void>;
}

function uploadFolder(config: AppStorage, viewer: string, parameterName: string): string {
  return `${uploadStoragePath(config)}/${viewer}/${hash(parameterName)}`;
}

function uploadId(reference: string): string {
  const id = UPLOAD_REFERENCE.exec(reference)?.[1];
  if (!id) throw new UploadError(400, 'Choose an uploaded file before running.');
  return id;
}

function isValidFilename(filename: string): boolean {
  return (
    filename.trim() !== '' &&
    filename !== '.' &&
    filename !== '..' &&
    Buffer.byteLength(filename, 'utf8') <= 255 &&
    ![...filename].some(
      (character) =>
        character === '/' || character === '\\' || character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127
    )
  );
}

function parseStoredUpload(raw: unknown, reference: string, maxBytes: number): StoredUpload {
  if (
    !isRecord(raw) ||
    raw.reference !== reference ||
    typeof raw.filename !== 'string' ||
    !isValidFilename(raw.filename) ||
    typeof raw.size !== 'number' ||
    !Number.isSafeInteger(raw.size) ||
    raw.size <= 0 ||
    raw.size > maxBytes ||
    typeof raw.createdAt !== 'number' ||
    !Number.isFinite(raw.createdAt)
  ) {
    throw new UploadError(409, 'This upload is incomplete or unreadable. Upload the file again.', {
      code: UPLOAD_UNAVAILABLE,
    });
  }
  return {
    reference,
    filename: raw.filename,
    size: raw.size,
    createdAt: raw.createdAt,
  };
}

export async function resolveUpload(
  store: UploadStore,
  config: AppStorage,
  viewer: string,
  parameterName: string,
  reference: string
) {
  const id = uploadId(reference);
  const folder = uploadFolder(config, viewer, parameterName);
  const upload = parseStoredUpload(await store.read(`${folder}/${id}.json`), reference, config.maxUploadFileSizeBytes);
  const path = `${folder}/${id}/${upload.filename}`;
  if ((await store.size(path)) !== upload.size)
    throw new UploadError(409, 'The uploaded file is missing or has changed. Upload the file again.', {
      code: UPLOAD_UNAVAILABLE,
    });
  return { path, upload };
}

export async function saveUploadStream(
  store: UploadStore,
  config: AppStorage,
  viewer: string,
  parameterName: string,
  filename: string,
  stream: ReadableStream<Uint8Array>,
  declaredSize?: number
): Promise<StoredUpload> {
  if (!isValidFilename(filename)) throw new UploadError(400, 'Choose a file with a valid filename.');
  if (declaredSize !== undefined && declaredSize > config.maxUploadFileSizeBytes)
    throw new UploadError(413, `Files must be at most ${MAX_UPLOAD_SIZE_LABEL}.`);
  const folder = uploadFolder(config, viewer, parameterName);
  const id = randomUUID();
  // Isolate each upload so its original extension survives and JSON data cannot collide with its sidecar.
  const path = `${folder}/${id}/${filename}`;
  await store.mkdir(`${folder}/${id}`);
  let size = 0;
  let validationError: UploadError | undefined;
  const boundedStream = stream.pipeThrough(
    new TransformStream<Uint8Array, Uint8Array>({
      transform(chunk, controller) {
        size += chunk.byteLength;
        if (size > config.maxUploadFileSizeBytes) {
          validationError = new UploadError(413, `Files must be at most ${MAX_UPLOAD_SIZE_LABEL}.`);
          throw validationError;
        }
        if (declaredSize !== undefined && size > declaredSize) {
          validationError = new UploadError(400, 'The upload exceeded its declared size.');
          throw validationError;
        }
        controller.enqueue(chunk);
      },
    })
  );
  try {
    await store.putStream(path, boundedStream);
    if (size === 0) throw new UploadError(400, 'Choose a non-empty file.');
    if (declaredSize !== undefined && size !== declaredSize)
      throw new UploadError(400, 'The upload did not match its declared size.');
    const upload: StoredUpload = {
      reference: `upload:${id}`,
      filename,
      size,
      createdAt: Date.now(),
    };
    // The sidecar is the completion marker; partially written files can never be selected for a run.
    await store.put(`${folder}/${id}.json`, Buffer.from(JSON.stringify(upload)));
    return upload;
  } catch (error) {
    await store.delete(path).catch(() => undefined);
    throw validationError ?? error;
  }
}

export function saveUpload(
  store: UploadStore,
  config: AppStorage,
  viewer: string,
  parameterName: string,
  filename: string,
  bytes: Uint8Array
): Promise<StoredUpload> {
  return saveUploadStream(
    store,
    config,
    viewer,
    parameterName,
    filename,
    new ReadableStream({
      start(controller) {
        controller.enqueue(bytes);
        controller.close();
      },
    }),
    bytes.byteLength
  );
}

import { isMap, parseDocument } from 'yaml';

import type { GuardrailDiagnostic } from '../shared/guardrails';
import { isRecord, nonEmptyString } from '../shared/values';

const ANSI_ESCAPE_SEQUENCE = new RegExp(`${String.fromCharCode(0x1b)}\\[[0-9;]*m`, 'g');
const GUARDRAILS_MARKER = /\[guardrails\]\s*(?:(WARNING|FAILURE):\s*)?checks\[(\d+)\]\s*(?:\(([^)]*)\))?\s*:\s*(.+)/;

function guardrailOperator(source: unknown): { nodeId: string; operatorName: string } | undefined {
  if (typeof source !== 'string') return undefined;
  // Restrict metadata to the generated leading docstring, never config/code that mentions Guardrails.
  const annotation = source.match(/^\s*"""\r?\n([\s\S]*?)\r?\n"""/);
  if (!annotation) return undefined;
  const doc = parseDocument(annotation[1], { schema: 'failsafe' });
  if (doc.errors.length > 0 || !isMap(doc.contents) || doc.get('template') !== 'guardrails') return undefined;
  const nodeId = nonEmptyString(doc.get('id'));
  if (!nodeId) return undefined;
  return { nodeId, operatorName: nonEmptyString(doc.get('name')) ?? nodeId };
}

function markers(texts: string[], operator?: { nodeId: string; operatorName: string }): GuardrailDiagnostic[] {
  return texts.flatMap((text) =>
    text
      .replace(ANSI_ESCAPE_SEQUENCE, '')
      .split(/\r?\n/)
      .flatMap((line) => {
        const match = line.match(GUARDRAILS_MARKER);
        if (!match || !Number.isSafeInteger(Number(match[2]))) return [];
        return [
          {
            ...operator,
            operatorName: operator?.operatorName ?? 'Guardrails',
            checkIndex: Number(match[2]),
            ...(match[3] ? { checkType: match[3] } : {}),
            severity: match[1] === 'WARNING' ? ('warning' as const) : ('failure' as const),
            message: match[4].trim(),
          },
        ];
      })
  );
}

function summaryText(value: string): string {
  return value
    .replace(/<br\s*\/?>|<\/(?:div|p)>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(
      /&(lt|gt|amp|quot|#39);/g,
      (entity) =>
        ({
          '&lt;': '<',
          '&gt;': '>',
          '&amp;': '&',
          '&quot;': '"',
          '&#39;': "'",
        })[entity] ?? entity
    );
}

export function commandGuardrailDiagnostics(
  command: Record<string, unknown>,
  entries: unknown[]
): GuardrailDiagnostic[] {
  const operator = guardrailOperator(command.command);
  if (!operator) return [];
  const texts = entries.flatMap((entry) =>
    isRecord(entry) && (entry.type === 'ansi' || entry.type === 'text') && typeof entry.data === 'string'
      ? [entry.data]
      : []
  );
  if (typeof command.errorTrace === 'string') texts.push(command.errorTrace);
  if (typeof command.errorSummaryHtml === 'string') texts.push(summaryText(command.errorSummaryHtml));
  return markers(texts, operator);
}

export function mergeGuardrailDiagnostics(
  diagnostics: GuardrailDiagnostic[],
  taskErrorTexts: string[] = []
): GuardrailDiagnostic[] {
  const merged = new Map<string, GuardrailDiagnostic>();
  for (const diagnostic of diagnostics) {
    const key = `${diagnostic.nodeId}\0${diagnostic.checkIndex}`;
    const previous = merged.get(key);
    if (!previous || diagnostic.severity === 'failure') merged.set(key, diagnostic);
  }
  // Jobs can retain the raised exception even when the failed cell's stdout was lost.
  // Without cell metadata, keep an unattributed check rather than guessing an operator.
  for (const diagnostic of markers(taskErrorTexts)) {
    const existing = [...merged.values()].some(
      (entry) =>
        entry.checkIndex === diagnostic.checkIndex &&
        entry.checkType === diagnostic.checkType &&
        entry.message === diagnostic.message &&
        entry.severity === diagnostic.severity
    );
    if (!existing) {
      merged.set(
        `task\0${diagnostic.checkIndex}\0${diagnostic.checkType}\0${diagnostic.severity}\0${diagnostic.message}`,
        diagnostic
      );
    }
  }
  return [...merged.values()];
}

import { isRecord } from '../shared/values';

export function runJobParameters(run: unknown): Record<string, string> {
  if (typeof run !== 'object' || run === null || !('job_parameters' in run) || !Array.isArray(run.job_parameters)) {
    return {};
  }
  const parameters: Record<string, string> = {};
  for (const parameter of run.job_parameters) {
    if (isRecord(parameter) && typeof parameter.name === 'string' && typeof parameter.value === 'string') {
      Object.defineProperty(parameters, parameter.name, {
        value: parameter.value,
        enumerable: true,
        configurable: true,
        writable: true,
      });
    }
  }
  return parameters;
}

import type { WorkspaceClient } from './workspaceClient';
import { fileSize, isMissingFile } from './workspaceFiles';
import { isOutputFilePath } from '../shared/fileOutputs';

export interface OutputFileStore {
  size(path: string): Promise<number | undefined>;
  download(path: string): Promise<ReadableStream<Uint8Array>>;
}

export function createOutputFileStore(client: WorkspaceClient, volume: string): OutputFileStore {
  return {
    async size(path) {
      if (!isOutputFilePath(path, { volumes: [volume] })) throw new Error('Invalid output file destination.');
      try {
        return await fileSize(client, path);
      } catch (error) {
        if (isMissingFile(error)) return undefined;
        throw error;
      }
    },
    async download(path) {
      if (!isOutputFilePath(path, { volumes: [volume] })) throw new Error('Invalid output file destination.');
      const result = await client.files.downloadFile({ filePath: path });
      if (!result.contents) throw new Error('The output file has no readable contents.');
      return result.contents;
    },
  };
}

import type { IAppRequest as Request } from '@databricks/appkit/dist/shared/src/plugin';
import type { RouteConfig } from '@databricks/appkit/dist/shared/src/plugin';

import {
  APP_REVISION_PARAM,
  FILE_OUTPUTS_PARAM,
  isOutputFilePath,
  MAX_OUTPUT_FILES,
  parseFileOutput,
  parseFileOutputBehavior,
  type FileOutputConfig,
  type WrittenFiles,
} from '../shared/fileOutputs';
import { RUNNER_REVISION_PARAM } from '../shared/publishedRunner';
import { idString, isRecord } from '../shared/values';
import { streamFileDownload } from './fileDownloads';
import { canAccessRun } from './fileUploads';
import { runJobParameters } from './jobParameters';
import type { OutputFileStore } from './outputFileStore';
import { isLegacyExportRun, manifestRevision, type FileOutputManifest } from './runRevision';

export function recordedFileOutput(
  payload: string | undefined,
  node: string,
  config: FileOutputConfig
): WrittenFiles | undefined {
  let parsed: unknown;
  try {
    parsed = JSON.parse(payload ?? '');
  } catch {
    return undefined;
  }
  if (!isRecord(parsed) || !Array.isArray(parsed.files)) return undefined;
  const matches = parsed.files.filter(
    (entry): entry is Record<string, unknown> => isRecord(entry) && entry.node === node
  );
  if (matches.length !== 1) return undefined;
  const [receipt] = matches;
  if (!Array.isArray(receipt.files) || receipt.files.length > MAX_OUTPUT_FILES) {
    return undefined;
  }
  const paths = receipt.files.map((file) => (isRecord(file) ? file.path : undefined));
  if (!paths.every((path): path is string => isOutputFilePath(path, config)) || new Set(paths).size !== paths.length) {
    return undefined;
  }
  const behavior = parseFileOutputBehavior(receipt.behavior);
  return {
    node,
    files: paths.map((path) => ({ path })),
    ...(behavior ? { behavior } : {}),
  };
}

interface Dependencies {
  jobId: string | undefined;
  manifest(): Promise<FileOutputManifest | undefined>;
  viewer(req: Request): string | undefined;
  notebookPath(): Promise<string | undefined>;
  getRun(id: number): Promise<unknown>;
  readPayload(taskId: string): Promise<string | undefined>;
  store(volume: string): OutputFileStore;
  report: (error: unknown) => void;
}

class DownloadError extends Error {
  readonly status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

export function registerOutputFileRoutes(route: (config: RouteConfig) => void, deps: Dependencies) {
  route({
    name: 'downloadOutput',
    method: 'get',
    path: '/run/:jobRunId/files/:outputId/:fileIndex/download',
    handler: async (req, res) => {
      try {
        if (req.method !== 'GET') throw new DownloadError(405, 'Use GET to download the file.');
        if (req.get('range'))
          throw new DownloadError(416, 'Partial downloads are not supported. Retry the full download.');
        const viewer = deps.viewer(req);
        if (!viewer) throw new DownloadError(401, 'Sign in through Databricks Apps to download files.');
        const runId = String(req.params.jobRunId);
        if (!/^[1-9][0-9]*$/.test(runId) || !Number.isSafeInteger(Number(runId))) {
          throw new DownloadError(404, 'Run not found.');
        }
        const manifest = await deps.manifest();
        if (!manifest || !deps.jobId) throw new DownloadError(409, 'File outputs are not configured.');
        const block = manifest.blocks.find((entry) => entry.type === 'output' && entry.id === req.params.outputId);
        if (!block?.fileOutput || !block.nodeId) throw new DownloadError(404, 'File output not found.');
        const run = await deps.getRun(Number(runId));
        if (
          !isRecord(run) ||
          String(run.job_id) !== deps.jobId ||
          !canAccessRun(run, viewer) ||
          isLegacyExportRun(run)
        ) {
          throw new DownloadError(404, 'Run not found.');
        }
        const params = runJobParameters(run);
        if (params[APP_REVISION_PARAM] !== manifestRevision(manifest)) {
          throw new DownloadError(
            409,
            'This run uses a different file-output configuration. Run the app again to download files.'
          );
        }
        let declared: unknown;
        try {
          declared = JSON.parse(String(params[FILE_OUTPUTS_PARAM]));
        } catch {
          throw new DownloadError(409, 'This run did not declare file outputs. Run the app again.');
        }
        const declaredOutput = parseFileOutput(isRecord(declared) ? declared[block.nodeId] : undefined);
        if (!declaredOutput || JSON.stringify(declaredOutput) !== JSON.stringify(parseFileOutput(block.fileOutput))) {
          throw new DownloadError(409, 'This run did not declare this file output. Run the app again.');
        }
        const task: unknown = Array.isArray(run.tasks) && run.tasks.length === 1 ? run.tasks[0] : undefined;
        const taskId = isRecord(task) ? idString(task.run_id) : undefined;
        const currentNotebookPath = await deps.notebookPath();
        const revision = params[RUNNER_REVISION_PARAM];
        const folder = currentNotebookPath?.slice(0, currentNotebookPath.lastIndexOf('/'));
        if (
          !isRecord(task) ||
          !isRecord(task.notebook_task) ||
          !taskId ||
          !folder ||
          typeof revision !== 'string' ||
          !/^[0-9a-f]{64}$/.test(revision) ||
          task.notebook_task.notebook_path !== `${folder}/runner-${revision}.designer.py`
        ) {
          throw new DownloadError(
            409,
            'This run’s published workflow could not be verified. Run the app again to download files.'
          );
        }
        const state = isRecord(run.state) ? run.state : {};
        if (
          !state.result_state &&
          !['TERMINATED', 'SKIPPED', 'INTERNAL_ERROR'].includes(String(state.life_cycle_state))
        ) {
          throw new DownloadError(409, 'Wait for the run to finish before downloading files.');
        }
        const receipt = recordedFileOutput(await deps.readPayload(taskId), block.nodeId, block.fileOutput);
        const indexText = String(req.params.fileIndex);
        const index = /^(0|[1-9][0-9]*)$/.test(indexText) ? Number(indexText) : -1;
        const file = receipt?.files[index];
        if (!file) throw new DownloadError(404, 'The run has no completed file at this output.');
        const store = deps.store(file.path.split('/').slice(2, 5).join('.'));
        const size = await store.size(file.path);
        if (size === undefined) {
          throw new DownloadError(404, 'This output file no longer exists at its recorded destination.');
        }
        const stream = await store.download(file.path);
        const filename = file.path.slice(file.path.lastIndexOf('/') + 1);
        await streamFileDownload(res, stream, filename, size, deps.report);
      } catch (error) {
        if (!(error instanceof DownloadError)) deps.report(error);
        if (res.headersSent) {
          res.destroy(error instanceof Error ? error : undefined);
        } else {
          res.status(error instanceof DownloadError ? error.status : 502).json({
            error:
              error instanceof DownloadError
                ? error.message
                : 'Could not read the output file. Check the App’s volume permissions and try again.',
          });
        }
      }
    },
  });
}

import { randomUUID } from 'node:crypto';

export const APP_PARAMETERS_PARAM = '_lb_app_parameters';

interface ForwardedHeaders {
  get(name: string): string | undefined;
}

// Apps ingress supplies these headers. Body parameters never establish the submitting user.
export async function runAttribution(
  headers: ForwardedHeaders,
  appId: string,
  readUserProfile?: (token: string) => Promise<{ id?: string; displayName?: string }>
): Promise<Record<string, string> | undefined> {
  const subject = headers.get('x-forwarded-user')?.trim();
  if (!subject) return undefined;
  const userId = /^(\d+)@\d+$/.exec(subject)?.[1] ?? subject;
  const email = headers.get('x-forwarded-email')?.trim() ?? '';
  let name = headers.get('x-forwarded-preferred-username')?.trim();
  const token = headers.get('x-forwarded-access-token')?.trim();
  if ((!name || name === email) && token && readUserProfile) {
    try {
      const profile = await readUserProfile(token);
      if (profile.id === userId) name = profile.displayName?.trim() || name;
    } catch {
      // Profile availability must not block a run whose ingress identity is already verified.
    }
  }
  return {
    _lb_app_id: appId,
    _lb_app_user_id: userId,
    _lb_app_user_name: name || email || userId,
    _lb_app_user_email: email,
    _lb_app_submission_id: randomUUID(),
  };
}

import { isRecord, nonEmptyString } from '../shared/values';

export interface VisibleRunPage {
  runs: Record<string, unknown>[];
  nextPageToken?: string;
}

// Bound each HTTP request, but preserve the Jobs cursor when other viewers fill the scan.
export async function scanVisibleRuns({
  pageToken,
  readPage,
  accessible,
  isComplete,
}: {
  pageToken?: string;
  readPage: (pageToken?: string) => Promise<unknown>;
  accessible: (run: unknown) => Promise<Record<string, unknown> | undefined>;
  isComplete: (runs: Record<string, unknown>[]) => boolean;
}): Promise<VisibleRunPage> {
  const runs: Record<string, unknown>[] = [];
  const seen = new Set<string>();
  if (pageToken) seen.add(pageToken);
  for (let page = 0; page < 8; page += 1) {
    const response = await readPage(pageToken);
    if (!isRecord(response) || (response.runs !== undefined && !Array.isArray(response.runs))) {
      throw new Error('The Job returned an unreadable run-history page.');
    }
    for (const run of Array.isArray(response.runs) ? response.runs : []) {
      const visible = await accessible(run);
      if (visible) runs.push(visible);
    }
    pageToken = nonEmptyString(response.next_page_token);
    if (!pageToken) return { runs };
    if (seen.has(pageToken)) throw new Error('The Job returned a repeated run-history cursor.');
    seen.add(pageToken);
    if (isComplete(runs)) break;
  }
  return { runs, nextPageToken: pageToken };
}

import { outputBlockTitle, type AppOutputBlock } from '../shared/appManifest';
import type { FileOutputBehavior } from '../shared/fileOutputs';
import { parseRunDiagnostics, type RunDiagnostics } from '../shared/guardrails';
import { isHtmlOutput } from '../shared/htmlOutputs';
import { errorMessage, isRecord, nonEmptyString } from '../shared/values';
import { recordedFileOutput } from './outputFiles';

const NO_OUTPUT_REASON = 'The run finished but returned no output. The notebook did not call dbutils.notebook.exit().';
const NO_OUTPUTS_REASON =
  'The run finished but returned a payload with no outputs. The notebook was published with nothing to return.';
const MISSING_OUTPUT_REASON =
  'This output is published with the app, but the run did not return it. That happens when the run predates the output being added, or when the app and its runner have drifted apart.';

const isReadableError = (value: unknown): value is { type: string; message: string } =>
  isRecord(value) && typeof value.type === 'string' && typeof value.message === 'string';
const isSchemaField = (value: unknown): value is { name: string; type: string } =>
  isRecord(value) && typeof value.name === 'string' && typeof value.type === 'string';

type ClassifiedEntry =
  | {
      outcome: 'malformed';
      index: number;
      id: string | undefined;
      reason: string;
    }
  | {
      outcome: 'computeError' | 'result' | 'html';
      index: number;
      id: string | undefined;
      payload: Record<string, unknown>;
    };

function classifyOutputEntry(entry: unknown, index: number): ClassifiedEntry {
  if (!isRecord(entry)) {
    return {
      outcome: 'malformed',
      index,
      id: undefined,
      reason: 'This output is not an object.',
    };
  }
  const id = nonEmptyString(entry.id);
  const malformed = (reason: string): ClassifiedEntry => ({
    outcome: 'malformed',
    index,
    id,
    reason,
  });
  if (entry.status === 'error') {
    return isReadableError(entry.error)
      ? { outcome: 'computeError', index, id, payload: entry }
      : malformed('This output reported an error, but the error was not readable.');
  }
  if (entry.status !== 'ok') {
    return malformed(`This output has an unrecognised status: ${JSON.stringify(entry.status)}`);
  }
  if (entry.kind === 'html') {
    return isHtmlOutput(entry.html) && typeof entry.target_node === 'string' && entry.target_port === undefined
      ? { outcome: 'html', index, id, payload: entry }
      : malformed('This HTML output is invalid or too large.');
  }
  if (!Array.isArray(entry.schema) || !Array.isArray(entry.rows)) {
    return malformed('This output reported success but is missing the schema or rows.');
  }
  if (!entry.schema.every(isSchemaField) || !entry.rows.every(isRecord)) {
    return malformed('This output reported success but its schema or rows are malformed.');
  }
  const fieldNames = entry.schema.map((field) => field.name);
  // Rows are keyed by column name downstream, so blank or duplicate names silently collapse
  // columns; reject the output rather than render data that has lost or merged a column.
  if (fieldNames.some((name) => name === '') || new Set(fieldNames).size !== fieldNames.length) {
    return malformed('This output reported success but its columns have blank or duplicate names.');
  }
  return { outcome: 'result', index, id, payload: entry };
}

function classifyMultiRunOutput(raw: string | undefined): (
  | { outcome: 'noPayload'; reason: string }
  | {
      outcome: 'outputs';
      outputs: ClassifiedEntry[];
      runtimeNodeStates: Map<string, boolean>;
    }
) &
  RunDiagnostics {
  if (raw === undefined || raw.trim() === '') {
    return { outcome: 'noPayload', reason: NO_OUTPUT_REASON };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    return {
      outcome: 'noPayload',
      reason: `The run returned output that is not valid JSON: ${errorMessage(err)}`,
    };
  }
  if (!isRecord(parsed) || Object.keys(parsed).length === 0) {
    return {
      outcome: 'noPayload',
      reason: 'The run returned an empty output object.',
    };
  }
  const diagnostics = parseRunDiagnostics(parsed);
  if (!Array.isArray(parsed.outputs)) {
    return {
      ...diagnostics,
      outcome: 'noPayload',
      reason: 'The run returned output with no outputs list, so it is not a multi-output payload.',
    };
  }
  const runtimeNodeStates = new Map<string, boolean>();
  if (isRecord(parsed.runtimeNodeStates)) {
    for (const [nodeId, state] of Object.entries(parsed.runtimeNodeStates)) {
      if (nodeId !== '' && isRecord(state) && typeof state.disabled === 'boolean') {
        runtimeNodeStates.set(nodeId, state.disabled);
      }
    }
  }
  if (parsed.outputs.length === 0 && runtimeNodeStates.size === 0) {
    return { outcome: 'noPayload', reason: NO_OUTPUTS_REASON, ...diagnostics };
  }
  // Classify entries independently so one malformed output does not discard valid siblings.
  return {
    outcome: 'outputs',
    outputs: parsed.outputs.map((entry, index) => classifyOutputEntry(entry, index)),
    runtimeNodeStates,
    ...diagnostics,
  };
}

const joinSource = (node: string | undefined, port: string | undefined): string | undefined =>
  node === undefined ? undefined : port === undefined ? node : `${node}.${port}`;

type MatchOutcome =
  | { outcome: 'malformed'; reason: string }
  | { outcome: 'computeError' | 'result'; payload: Record<string, unknown> }
  | { outcome: 'html'; html: string }
  | { outcome: 'missing'; reason: string };
type OutputSection = {
  key: string;
  id?: string;
  title: string;
  source?: string;
  chartSpec?: Record<string, unknown>;
  files?: { path: string }[];
  fileBehavior?: FileOutputBehavior;
  disabled?: boolean;
  outcome: MatchOutcome;
};

function matchedOutcome(entry: ClassifiedEntry): MatchOutcome {
  if (entry.outcome === 'html') {
    return isHtmlOutput(entry.payload.html)
      ? { outcome: 'html', html: entry.payload.html }
      : {
          outcome: 'malformed',
          reason: 'This HTML output is invalid or too large.',
        };
  }
  return entry.outcome === 'malformed'
    ? { outcome: 'malformed', reason: entry.reason }
    : { outcome: entry.outcome, payload: entry.payload };
}

export function matchRunOutputs(declared: AppOutputBlock[], raw: string | undefined) {
  const multi = classifyMultiRunOutput(raw);
  const diagnostics = parseRunDiagnostics(multi);
  if (multi.outcome !== 'outputs' && !declared.some((block) => block.fileOutput || block.disabled === true)) {
    return { outcome: 'noPayload', reason: multi.reason, ...diagnostics };
  }
  const classified = multi.outcome === 'outputs' ? multi.outputs : [];
  const runtimeNodeStates = multi.outcome === 'outputs' ? multi.runtimeNodeStates : undefined;
  const consumed = new Set<number>();

  // The run may include other nodes and ports, but only published output blocks are exposed.
  const outputs: OutputSection[] = declared.map((output) => {
    // Entries are keyed by the (node, port) of the cell's display(ctx[...]) line, not an output id.
    // Payload empties read as undefined, so normalize declared empties the same way.
    const declaredNode = output.nodeId === '' ? undefined : output.nodeId;
    const declaredPort = output.port === '' ? undefined : output.port;
    // A malformed entry has no (node, port), so it binds to its block by id and surfaces as malformed.
    const matches = (entry: ClassifiedEntry) =>
      entry.outcome === 'malformed'
        ? entry.id !== undefined && entry.id === output.id
        : nonEmptyString(entry.payload.target_node) === declaredNode &&
          (entry.payload.kind === 'html') === (output.kind === 'html') &&
          nonEmptyString(entry.payload.target_port) === declaredPort;
    // Prefer an unconsumed entry; blocks published at the same (node, port) may share one.
    const found = classified.find((entry) => !consumed.has(entry.index) && matches(entry)) ?? classified.find(matches);
    const source = joinSource(declaredNode, declaredPort);
    const fileReceipt = output.fileOutput ? recordedFileOutput(raw, output.nodeId, output.fileOutput) : undefined;
    const ownDisabled = runtimeNodeStates?.get(output.nodeId) ?? output.disabled;
    const groupDisabled = output.parentGroupId === undefined ? undefined : runtimeNodeStates?.get(output.parentGroupId);
    const disabled =
      ownDisabled === true || groupDisabled === true
        ? true
        : ownDisabled === undefined && groupDisabled === undefined
          ? undefined
          : false;
    const section = {
      key: `declared:${output.id}`,
      id: output.id,
      title: outputBlockTitle(output),
      ...(source === undefined ? {} : { source }),
      ...(output.chartSpec === undefined ? {} : { chartSpec: output.chartSpec }),
      ...(output.fileOutput ? { files: fileReceipt?.files ?? [] } : {}),
      ...(fileReceipt?.behavior ? { fileBehavior: fileReceipt.behavior } : {}),
      ...(disabled === undefined ? {} : { disabled }),
    };
    if (found === undefined) {
      return {
        ...section,
        outcome: { outcome: 'missing', reason: MISSING_OUTPUT_REASON },
      };
    }
    consumed.add(found.index);
    return { ...section, outcome: matchedOutcome(found) };
  });

  return { outcome: 'outputs', outputs, ...diagnostics };
}

import { randomUUID } from 'node:crypto';

import { isReservedParameter } from '../shared/appManifest';
import { validateFileFormat } from '../shared/fileFormats';
import { FILE_OUTPUTS_PARAM, OUTPUT_NAMESPACE_PARAM, type FileOutputConfig } from '../shared/fileOutputs';
import { isValidMultiselectConfig, isValidMultiselectValue } from '../shared/multiselect';
import { RUNNER_REVISION_PARAM, type PublishedRunner } from '../shared/publishedRunner';
import type { AppStorage } from '../shared/storageConfig';
import { UPLOAD_UNAVAILABLE, UPLOAD_UNAVAILABLE_MESSAGE } from '../shared/storageConfig';
import { APP_VIEWER_PARAM, UploadError, resolveUpload, type UploadStore } from './fileUploads';
import { APP_PARAMETERS_PARAM } from './runAttribution';

export { isReservedParameter };

interface ParameterManifest {
  runner?: PublishedRunner;
  storage?: AppStorage;
  blocks?: { type: string; nodeId?: string; fileOutput?: FileOutputConfig }[];
  parameters: {
    name: string;
    label: string;
    type: string;
    defaultValue: string;
    choices?: string[];
    fileFormats?: string[];
  }[];
}

const DISPLAY_OUTPUTS_FOR_PARAM = 'ld_display_outputs_for';
const COLLECT_ROW_COUNTS_PARAM = '_lb_collect_row_counts';

function displayOutputsFor(manifest: ParameterManifest): string {
  return Array.from(
    new Set(
      (manifest.blocks ?? []).flatMap((block) =>
        block.type === 'output' && typeof block.nodeId === 'string' && block.nodeId !== '' ? [block.nodeId] : []
      )
    )
  ).join(',');
}

export async function resolveRunParameters(
  manifest: ParameterManifest,
  submitted: Record<string, unknown>,
  viewer: string | undefined,
  store: UploadStore
): Promise<
  { ok: true; params: Record<string, string> } | { ok: false; error: string; code?: typeof UPLOAD_UNAVAILABLE }
> {
  // Pin hidden defaults as well as exposed inputs to the selected publication. A Job reset can
  // race submission, so inheriting the Job's newer defaults would mix publication versions.
  const params: Record<string, string> = { ...manifest.runner?.parameters };
  const filenames = new Map<string, string>();
  const fileOutputs = Object.fromEntries(
    (manifest.blocks ?? []).flatMap((block) =>
      block.type === 'output' && block.nodeId && block.fileOutput ? [[block.nodeId, block.fileOutput]] : []
    )
  );
  if (!viewer)
    return {
      ok: false,
      error: 'Sign in through Databricks Apps to run this app.',
    };
  for (const parameter of manifest.parameters) {
    if (isReservedParameter(parameter.name)) continue;
    const raw = submitted[parameter.name];
    if (parameter.type === 'multiselect') {
      const resolved = raw === undefined ? parameter.defaultValue : raw;
      if (
        !isValidMultiselectConfig(parameter.choices, parameter.defaultValue) ||
        !isValidMultiselectValue(resolved, parameter.choices ?? [])
      ) {
        return {
          ok: false,
          error: `"${parameter.label}" must contain only the offered choices.`,
        };
      }
      params[parameter.name] = resolved;
      continue;
    }
    if (
      raw !== undefined &&
      raw !== null &&
      typeof raw !== 'string' &&
      typeof raw !== 'number' &&
      typeof raw !== 'boolean'
    ) {
      return {
        ok: false,
        error: `"${parameter.label}" must be a string, number or boolean.`,
      };
    }
    const value = raw === undefined || raw === null ? '' : String(raw);
    const resolved = value.trim() === '' ? parameter.defaultValue : value;
    if (parameter.type === 'file') {
      if (!manifest.storage || !viewer)
        return {
          ok: false,
          error: UPLOAD_UNAVAILABLE_MESSAGE,
          code: UPLOAD_UNAVAILABLE,
        };
      try {
        const { path, upload } = await resolveUpload(store, manifest.storage, viewer, parameter.name, resolved);
        const formatError = validateFileFormat(upload.filename, parameter.fileFormats);
        if (formatError) return { ok: false, error: formatError };
        params[parameter.name] = path;
        filenames.set(parameter.name, upload.filename);
      } catch (error) {
        if (!(error instanceof UploadError)) {
          return {
            ok: false,
            error: 'Could not verify the uploaded file. Try Run again after storage is available.',
          };
        }
        if (error.code === UPLOAD_UNAVAILABLE) return { ok: false, error: error.message, code: UPLOAD_UNAVAILABLE };
        if ([400, 404, 409].includes(error.status)) {
          return {
            ok: false,
            error: `${error.message} Upload the file again.`,
            code: UPLOAD_UNAVAILABLE,
          };
        }
        return { ok: false, error: error.message };
      }
      continue;
    }
    if (parameter.type === 'dropdown' && Array.isArray(parameter.choices) && !parameter.choices.includes(resolved)) {
      return {
        ok: false,
        error: `"${parameter.label}" must be one of the offered choices.`,
      };
    }
    params[parameter.name] = resolved;
  }
  // Override all server-owned controls so a partially completed republish cannot change this
  // manifest's output policy through newer Job defaults.
  const displayedNodes = displayOutputsFor(manifest);
  if (displayedNodes !== '') {
    params[DISPLAY_OUTPUTS_FOR_PARAM] = displayedNodes;
    params[COLLECT_ROW_COUNTS_PARAM] = 'true';
  }
  // An empty override is intentional: a partially completed republish may leave newer
  // file-writing Job defaults behind the current manifest. Never inherit that policy.
  params[FILE_OUTPUTS_PARAM] = JSON.stringify(fileOutputs);
  params._lb_file_output_volume = manifest.runner?.parameters._lb_file_output_volume ?? '';
  if (manifest.runner) params[RUNNER_REVISION_PARAM] = manifest.runner.revision;
  // The runtime adds an attempt ID and node ID beneath this server-owned submission namespace.
  // Consumer parameters must not choose/reuse a previous run's artifact directory.
  if (Object.keys(fileOutputs).length > 0) params[OUTPUT_NAMESPACE_PARAM] = randomUUID();
  params[APP_VIEWER_PARAM] = viewer;
  // Preserve labels and resolved values at submission time, including inputs later removed or
  // renamed on republish. File reporting exposes the filename rather than its private storage path.
  params[APP_PARAMETERS_PARAM] = JSON.stringify(
    Object.fromEntries(
      manifest.parameters
        .filter(({ name }) => !isReservedParameter(name))
        .map((parameter) => [
          parameter.name,
          {
            label: parameter.label,
            type: parameter.type,
            value: filenames.get(parameter.name) ?? params[parameter.name],
          },
        ])
    )
  );
  return { ok: true, params };
}

import { createHash } from 'node:crypto';

import type { FileOutputConfig } from '../shared/fileOutputs';
import type { AppStorage } from '../shared/storageConfig';
import { runJobParameters } from './jobParameters';

export interface FileOutputManifest {
  storage?: AppStorage;
  blocks: {
    type: string;
    id?: string;
    nodeId?: string;
    port?: string;
    fileOutput?: FileOutputConfig;
  }[];
  parameters: { name: string }[];
}

export function manifestRevision(manifest: FileOutputManifest): string {
  // Runner notebook identity is verified separately. Labels, ordering, defaults and publication
  // timestamps do not change a completed write's destination or ownership.
  const outputs = manifest.blocks
    .filter((block) => block.type === 'output')
    .map((block) => ({
      id: block.id ?? '',
      nodeId: block.nodeId,
      port: block.port,
      ...(block.fileOutput
        ? {
            fileOutput: {
              volumes: [...new Set(block.fileOutput.volumes)].sort(),
            },
          }
        : {}),
    }))
    .sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
  const revision = createHash('sha256')
    .update(
      JSON.stringify({
        storage: manifest.storage && {
          volume: manifest.storage.volume,
          path: manifest.storage.path,
        },
        parameters: manifest.parameters.map((parameter) => parameter.name).sort(),
        outputs,
      })
    )
    .digest('hex');
  return `file-outputs-v1:${revision}`;
}

// Old converter runs can still be present in this Job's history after republishing.
export const isLegacyExportRun = (run: unknown) => typeof runJobParameters(run)._lb_export_request === 'string';

import type { WorkspaceClient } from './workspaceClient';
import type { IAppRequest as Request, IAppResponse as Response } from '@databricks/appkit/dist/shared/src/plugin';
import type { RouteConfig } from '@databricks/appkit/dist/shared/src/plugin';
import { format } from 'node:util';

import { createWorkspaceClient, type IAppRouter, type ITelemetry, SeverityNumber } from '@databricks/appkit';
import { appManifestSchema, isReservedParameter, type AppManifest, type AppOutputBlock } from '../shared/appManifest';
import { APP_REVISION_PARAM } from '../shared/fileOutputs';
import { APP_UPDATING_MESSAGE, isPublishedRunner } from '../shared/publishedRunner';
import { UPLOAD_REFERENCE } from '../shared/storageConfig';
import { errorMessage, idString, isRecord, nonEmptyString, positiveInt } from '../shared/values';
import { isSameOriginBrowserRequest } from './browserRequestOrigin';
import { exportedModelToRunPayload, findNotebookModelValue } from './exportedRunOutput';
import { canAccessRun, viewerKey } from './fileUploads';
import { runJobParameters } from './jobParameters';
import { registerOutputFileRoutes } from './outputFiles';
import { createOutputFileStore } from './outputFileStore';
import { runAttribution } from './runAttribution';
import { scanVisibleRuns, type VisibleRunPage } from './runHistory';
import { matchRunOutputs } from './runOutputs';
import { resolveRunParameters } from './runParameters';
import { isLegacyExportRun, manifestRevision } from './runRevision';
import { registerUploadRoutes } from './uploads';
import { createUploadStore } from './uploadStore';

// Publishing writes the manifest beside the runner notebook in the app's publisher-owned folder, outside
// the git-backed source and client/dist, so it is never served publicly.
const MANIFEST_FILENAME = 'designerApp.json';
// SKIPPED and INTERNAL_ERROR are terminal even when no task ran.
const TERMINAL_LIFE_CYCLE_STATES = new Set(['TERMINATED', 'SKIPPED', 'INTERNAL_ERROR']);

type RunSummary = {
  jobRunId: string;
  taskRunId?: string;
  endTime?: number;
  startTime?: number;
  setupDurationMs?: number;
  executionDurationMs?: number;
  runPageUrl?: string;
  resultState?: string;
  lifeCycleState?: string;
  parameters?: Record<string, string>;
  parameterDisplayValues?: Record<string, string>;
};

export function createDesignerRuntime(client: WorkspaceClient, telemetry: ITelemetry) {
  const JOB_ID = process.env.DATABRICKS_JOB_ID?.trim() || undefined;
  const APP_ID = process.env.DATABRICKS_APP_ID?.trim() || process.env.DATABRICKS_CLIENT_ID?.trim();
  const appUrl = process.env.DATABRICKS_APP_URL;
  const report = (...args: unknown[]) =>
    telemetry.emit({
      severityNumber: SeverityNumber.ERROR,
      body: format(...args),
    });
  const wsClient = () => client;
  const appKitUploadStore = (storage: Parameters<typeof createUploadStore>[1]) => createUploadStore(client, storage);
  const appKitOutputFileStore = (volume: string) => createOutputFileStore(client, volume);

  // Runner/access checks consume the Jobs REST shape, including recorded parameter maps.
  async function readWorkspaceJson(
    path: string,
    query: Record<string, string | number | boolean | undefined>
  ): Promise<unknown> {
    const response = await wsClient().request({
      method: 'GET',
      path,
      query: Object.fromEntries(
        Object.entries(query)
          .filter(([, value]) => value !== undefined)
          .map(([key, value]) => [key, String(value)])
      ),
    });
    return response.json();
  }

  const readJob = () => readWorkspaceJson('/api/2.2/jobs/get', { job_id: JOB_ID });
  const readRun = (runId: string | number) => readWorkspaceJson('/api/2.2/jobs/runs/get', { run_id: runId });

  function jobNotebookPaths(job: unknown): (string | undefined)[] {
    const tasks =
      isRecord(job) && isRecord(job.settings) && Array.isArray(job.settings.tasks) ? job.settings.tasks : [];
    return tasks.map((task: unknown) =>
      isRecord(task) && isRecord(task.notebook_task) ? nonEmptyString(task.notebook_task.notebook_path) : undefined
    );
  }

  const READ_RETRY_ATTEMPTS = 3;
  const READ_RETRY_BACKOFF_MS = 1000;

  const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

  // Only reads get application-level retries; writes rely on the SDK transport.
  async function retryRead<T>(read: () => Promise<T>): Promise<T> {
    let lastError: unknown;
    for (let attempt = 1; attempt <= READ_RETRY_ATTEMPTS; attempt += 1) {
      try {
        return await read();
      } catch (err) {
        lastError = err;
        if (attempt < READ_RETRY_ATTEMPTS) {
          await sleep(READ_RETRY_BACKOFF_MS);
        }
      }
    }
    throw lastError;
  }

  // Polled run-status reads reuse the cached manifest; other routes pass forceFresh, so a republish
  // takes effect without a redeploy.
  let cachedManifest: AppManifest | undefined;
  const loadManifest = async (forceFresh = false): Promise<AppManifest | undefined> => {
    if (!forceFresh && cachedManifest !== undefined) {
      return cachedManifest;
    }
    const manifest = await readManifest();
    // A failed fresh read must not keep stale execution or file policies active.
    if (manifest !== undefined || forceFresh) {
      cachedManifest = manifest;
    }
    return manifest;
  };

  function manifestFolderFromNotebookPath(notebookPath: string): string {
    const lastSlash = notebookPath.lastIndexOf('/');
    return lastSlash <= 0 ? notebookPath : notebookPath.slice(0, lastSlash);
  }

  // All immutable runner revisions share the App folder, so resolve it from the bound Job once.
  let cachedManifestFolder: string | undefined;

  async function resolveManifestFolder(): Promise<string | undefined> {
    if (cachedManifestFolder !== undefined) {
      return cachedManifestFolder;
    }
    if (JOB_ID === undefined) {
      return undefined;
    }
    try {
      const notebookPath = jobNotebookPaths(await readJob()).find((path) => path !== undefined);
      if (notebookPath === undefined) {
        report('Could not find the runner notebook path on job', JOB_ID, 'to locate the app manifest');
        return undefined;
      }
      cachedManifestFolder = manifestFolderFromNotebookPath(notebookPath);
      return cachedManifestFolder;
    } catch (err) {
      report('Could not read the runner job to locate the app manifest', err);
      return undefined;
    }
  }

  async function readManifest() {
    const folder = await resolveManifestFolder();
    if (folder === undefined) {
      return undefined;
    }
    const manifestPath = `${folder}/${MANIFEST_FILENAME}`;
    try {
      const exported = await readWorkspaceJson('/api/2.0/workspace/export', {
        path: manifestPath,
        format: 'SOURCE',
      });
      if (!isRecord(exported) || typeof exported.content !== 'string') {
        return undefined;
      }
      return parseManifest(Buffer.from(exported.content, 'base64').toString('utf8'));
    } catch (err) {
      report('Could not read the app manifest from', manifestPath, err);
      return undefined;
    }
  }

  function parseManifest(raw: string): AppManifest | undefined {
    try {
      return appManifestSchema.safeParse(JSON.parse(raw)).data;
    } catch {
      return undefined;
    }
  }

  const requestViewer = (req: Request) => viewerKey(req.get('x-forwarded-user'), JOB_ID);

  async function accessibleRun(
    run: unknown,
    req: Request,
    hydrate = false
  ): Promise<Record<string, unknown> | undefined> {
    if (!runBelongsToJob(run, JOB_ID)) return undefined;
    const manifest = await loadManifest();
    if (!manifest) return undefined;
    let detail = run;
    if (hydrate && isRecord(run) && !Array.isArray(run.job_parameters)) {
      const id = idString(run.run_id);
      if (!id) return undefined;
      detail = await readRun(id);
    }
    return isRecord(detail) &&
      !isLegacyExportRun(detail) &&
      runBelongsToJob(detail, JOB_ID) &&
      canAccessRun(detail, requestViewer(req))
      ? detail
      : undefined;
  }

  // Guard every client-supplied run ID before reading output or cancelling it.
  async function readViewerRun(req: Request, res: Response) {
    const jobRunId = idString(req.params.jobRunId);
    if (jobRunId === undefined) {
      res.status(400).json({ error: 'jobRunId must be a positive integer.' });
      return undefined;
    }
    let run;
    try {
      run = await retryRead(() => readRun(jobRunId));
    } catch (err) {
      res.status(502).json({
        error: `Could not read run ${jobRunId}: ${errorMessage(err)}`,
      });
      return undefined;
    }
    const visibleRun = await accessibleRun(run, req);
    if (visibleRun === undefined) {
      res.status(404).json({ error: `Run ${jobRunId} is not a run of this app.` });
      return undefined;
    }
    return { jobRunId, run: visibleRun };
  }

  async function declaredOutputs() {
    return (await loadManifest())?.blocks.filter((block): block is AppOutputBlock => block.type === 'output') ?? [];
  }

  // The runs/export CODE view carries the displayed command results.
  async function readRunExport(taskRunId: string): Promise<unknown> {
    const exported = await retryRead(() =>
      wsClient().jobs.exportRun({
        runId: BigInt(taskRunId),
        viewsToExport: 'CODE',
      })
    );
    const views = isRecord(exported) && Array.isArray(exported.views) ? exported.views : [];
    // Probe with the decoder rather than a substring: a base64-wrapped view never contains the literal marker.
    const view: unknown = views.find(
      (candidate) => isRecord(candidate) && findNotebookModelValue(candidate.content) !== undefined
    );
    return isRecord(view) ? view.content : undefined;
  }

  interface CompletedTaskOutput {
    payload?: string;
    failureReason?: string;
    readError?: string;
  }

  const COMPLETED_RESULT_CACHE_LIMIT = 20;
  const COMPLETED_RESULT_CACHE_TTL_MS = 5 * 60 * 1000;
  const completedTaskOutputs = new Map<string, { expiresAt: number; value: Promise<CompletedTaskOutput> }>();

  async function readCompletedTaskOutput(taskRunId: string, failed = false): Promise<CompletedTaskOutput> {
    const key = `${taskRunId}:${failed}`;
    const now = Date.now();
    const cached = completedTaskOutputs.get(key);
    if (cached && cached.expiresAt > now) return cached.value;
    for (const [id, entry] of completedTaskOutputs) {
      if (entry.expiresAt <= now) completedTaskOutputs.delete(id);
    }
    const value = Promise.allSettled([
      readRunExport(taskRunId),
      failed ? retryRead(() => wsClient().jobs.getRunOutput({ runId: BigInt(taskRunId) })) : Promise.resolve(undefined),
    ]).then(([exported, taskOutput]) => {
      const taskError = taskOutput.status === 'fulfilled' && isRecord(taskOutput.value) ? taskOutput.value : undefined;
      const taskErrorTexts = [taskError?.error, taskError?.errorTrace].filter(
        (text): text is string => typeof text === 'string'
      );
      const html = exported.status === 'fulfilled' ? exported.value : undefined;
      // Retention gaps and transient read errors can recover; do not retain them for the full cache TTL.
      if (exported.status === 'rejected' || taskOutput.status === 'rejected' || html === undefined) {
        const entry = completedTaskOutputs.get(key);
        if (entry?.value === value) entry.expiresAt = Date.now() + 5000;
      }
      return {
        payload: exportedModelToRunPayload(html, taskErrorTexts),
        failureReason: nonEmptyString(taskError?.error) ?? nonEmptyString(taskError?.errorTrace),
        ...(exported.status === 'rejected' ? { readError: errorMessage(exported.reason) } : {}),
      };
    });
    // Cache only after access checks, and share the in-flight read across concurrent viewers/pollers.
    completedTaskOutputs.set(key, {
      expiresAt: now + COMPLETED_RESULT_CACHE_TTL_MS,
      value,
    });
    while (completedTaskOutputs.size > COMPLETED_RESULT_CACHE_LIMIT) {
      const oldest = completedTaskOutputs.keys().next().value;
      if (oldest === undefined) break;
      completedTaskOutputs.delete(oldest);
    }
    return value;
  }

  async function readRunOutputPayload(taskRunId: string): Promise<string | undefined> {
    return (await readCompletedTaskOutput(taskRunId)).payload;
  }

  async function readRunResult(taskRunId: string | undefined, failed = false) {
    if (taskRunId === undefined) {
      return {
        outcome: 'noPayload',
        reason: 'The run reported no task, so it has no output to read.',
      };
    }
    try {
      // Jobs requires the task run ID here, not the job run ID.
      const { payload, failureReason, readError } = await readCompletedTaskOutput(taskRunId, failed);
      const result = matchRunOutputs(await declaredOutputs(), payload);
      return {
        ...result,
        ...(failureReason ? { failureReason } : {}),
        ...(result.outcome === 'noPayload' && readError
          ? { reason: `Could not read the run output: ${readError}` }
          : {}),
      };
    } catch (err) {
      return {
        outcome: 'noPayload',
        reason: `Could not read the run output: ${errorMessage(err)}`,
      };
    }
  }

  const LAST_RUN_PAGE_SIZE = 25;
  const SUCCESSFUL_RESULT_STATES = new Set(['SUCCESS', 'SUCCESS_WITH_FAILURES']);

  type ListRunsQuery = {
    active_only?: boolean;
    completed_only?: boolean;
    expand_tasks?: boolean;
    limit: number;
    page_token?: string;
  };

  async function collectVisibleRuns(
    req: Request,
    options: ListRunsQuery,
    isComplete: (visible: Record<string, unknown>[]) => boolean
  ): Promise<VisibleRunPage> {
    return scanVisibleRuns({
      pageToken: options.page_token,
      // The SDK iterator consumes page tokens internally; use its authenticated transport to
      // return a continuation when this request's scan budget is exhausted.
      readPage: (pageToken) =>
        readWorkspaceJson('/api/2.2/jobs/runs/list', {
          ...options,
          job_id: JOB_ID,
          page_token: pageToken,
        }),
      accessible: (run) => accessibleRun(run, req, true),
      isComplete,
    });
  }

  function isSuccessfulRun(run: unknown): run is Record<string, unknown> {
    return (
      isRecord(run) &&
      idString(run.run_id) !== undefined &&
      isRecord(run.state) &&
      typeof run.state.result_state === 'string' &&
      SUCCESSFUL_RESULT_STATES.has(run.state.result_state)
    );
  }

  const startedAt = (run: Record<string, unknown>) => positiveInt(run.start_time) ?? 0;
  const newestFirst = (a: Record<string, unknown>, b: Record<string, unknown>) => startedAt(b) - startedAt(a);

  function selectLastSuccessfulRun(runs: Record<string, unknown>[]): Record<string, unknown> | undefined {
    return runs.filter(isSuccessfulRun).sort(newestFirst)[0];
  }

  function selectActiveRun(runs: Record<string, unknown>[]): Record<string, unknown> | undefined {
    return runs.filter((run) => idString(run.run_id) !== undefined).sort(newestFirst)[0];
  }

  const lifeCycleStateOf = (run: Record<string, unknown>) =>
    isRecord(run.state) ? nonEmptyString(run.state.life_cycle_state) : undefined;

  const resultStateOf = (run: Record<string, unknown>) =>
    isRecord(run.state) ? nonEmptyString(run.state.result_state) : undefined;

  function summarizeLastRun(run: Record<string, unknown>): RunSummary | undefined {
    const jobRunId = idString(run.run_id);
    if (jobRunId === undefined) {
      return undefined;
    }
    const firstTask = (Array.isArray(run.tasks) ? run.tasks : []).find(isRecord);
    const summary: RunSummary = { jobRunId };
    const taskRunId = idString(firstTask?.run_id);
    if (taskRunId !== undefined) summary.taskRunId = taskRunId;
    const endTime = positiveInt(run.end_time);
    if (endTime !== undefined) summary.endTime = endTime;
    const startTime = positiveInt(run.start_time);
    if (startTime !== undefined) summary.startTime = startTime;
    const setupDurationMs = positiveInt(run.setup_duration);
    if (setupDurationMs !== undefined) summary.setupDurationMs = setupDurationMs;
    const executionDurationMs = positiveInt(run.execution_duration);
    if (executionDurationMs !== undefined) summary.executionDurationMs = executionDurationMs;
    if (typeof run.run_page_url === 'string' && run.run_page_url !== '') summary.runPageUrl = run.run_page_url;
    return summary;
  }

  function runParameterData(
    run: Record<string, unknown>
  ): Pick<RunSummary, 'parameters' | 'parameterDisplayValues'> | undefined {
    if (!Array.isArray(run.job_parameters)) {
      return undefined;
    }
    const params: Record<string, string> = {};
    const displayValues: Record<string, string> = {};
    for (const [name, value] of Object.entries(runJobParameters(run))) {
      if (isReservedParameter(name) || !cachedManifest?.parameters.some((parameter) => parameter.name === name)) {
        continue;
      }
      const isFile = cachedManifest?.parameters.some(
        (parameter) => parameter.name === name && parameter.type === 'file'
      );
      if (isFile) {
        const parts = value.split('/');
        const reference = `upload:${parts.at(-2)}`;
        if (UPLOAD_REFERENCE.test(reference)) {
          params[name] = reference;
          const filename = parts.at(-1);
          if (filename) displayValues[name] = filename;
        } else {
          params[name] = '';
        }
      } else {
        params[name] = value;
      }
    }
    return {
      parameters: params,
      ...(Object.keys(displayValues).length === 0 ? {} : { parameterDisplayValues: displayValues }),
    };
  }

  function runBelongsToJob(run: unknown, jobId: string | undefined) {
    if (jobId === undefined || !isRecord(run)) {
      return false;
    }
    return String(run.job_id) === jobId;
  }

  const RUN_HISTORY_DEFAULT_WINDOW = 100;
  const RUN_HISTORY_MAX_WINDOW = 200;
  // listRuns caps page size at 26.
  const RUN_HISTORY_PAGE_SIZE = 25;

  function summarizeHistoryRun(run: Record<string, unknown>) {
    const summary = summarizeLastRun(run);
    if (summary === undefined) {
      return undefined;
    }
    delete summary.taskRunId;
    const resultState = resultStateOf(run);
    if (resultState !== undefined) summary.resultState = resultState;
    const lifeCycleState = lifeCycleStateOf(run);
    if (lifeCycleState !== undefined) summary.lifeCycleState = lifeCycleState;
    const parameterData = runParameterData(run);
    if (parameterData !== undefined) Object.assign(summary, parameterData);
    return summary;
  }

  function summarizeRunHistory(page: VisibleRunPage) {
    return {
      entries: [...page.runs].sort(newestFirst).flatMap((run) => summarizeHistoryRun(run) ?? []),
      hasMore: page.nextPageToken !== undefined,
      nextPageToken: page.nextPageToken,
    };
  }

  function resolveHistoryWindow(raw: unknown) {
    const parsed = Number(raw);
    if (!Number.isSafeInteger(parsed) || parsed <= 0) {
      return RUN_HISTORY_DEFAULT_WINDOW;
    }
    return Math.min(parsed, RUN_HISTORY_MAX_WINDOW);
  }

  function registerRoutes(app: IAppRouter, route: (config: RouteConfig) => void) {
    // These responses contain per-viewer filenames and results, never shared cache entries.
    app.use((req, res, next) => {
      res.setHeader('Cache-Control', 'no-store');
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
      if (
        !isSameOriginBrowserRequest({
          origin: req.get('origin'),
          // Apps ingress can rewrite Host; the runtime URL names the public origin.
          appUrl: appUrl || `${req.protocol}://${req.get('host')}`,
          fetchSite: req.get('sec-fetch-site'),
        })
      ) {
        res.status(403).json({ error: 'Open the App directly to use its APIs.' });
        return;
      }
      next();
    });

    registerOutputFileRoutes(route, {
      jobId: JOB_ID,
      manifest: () => loadManifest(true),
      viewer: requestViewer,
      notebookPath: async () => {
        const paths = jobNotebookPaths(await readJob());
        return paths.length === 1 ? paths[0] : undefined;
      },
      getRun: readRun,
      readPayload: readRunOutputPayload,
      store: appKitOutputFileStore,
      report: (error) => report('Output file download failed', error),
    });

    registerUploadRoutes(route, {
      manifest: () => loadManifest(true),
      viewer: requestViewer,
      store: appKitUploadStore,
      report: (error) => report('Uploaded file download failed', error),
    });

    route({
      name: 'config',
      method: 'get',
      path: '/config',
      handler: async (_req, res) => {
        try {
          const manifest = await loadManifest(true);
          if (manifest === undefined) {
            res.json({
              manifest: null,
              runnable: false,
              notRunnableReason: 'noManifest',
            });
            return;
          }
          // Hidden runner defaults are execution policy, not consumer-visible configuration.
          const { runner: _runner, ...publicManifest } = manifest;
          if (JOB_ID === undefined) {
            res.json({
              manifest: publicManifest,
              runnable: false,
              notRunnableReason: 'noJob',
            });
            return;
          }
          const runnable = isPublishedRunner(manifest.runner, await readJob());
          res.json({
            manifest: publicManifest,
            runnable,
            ...(runnable ? {} : { notRunnableReason: 'updating' }),
          });
        } catch (err) {
          report('Designer request failed: %O', err);
          res.status(500).json({ error: 'The app could not read its own configuration.' });
        }
      },
    });

    route({
      name: 'lastRun',
      method: 'get',
      path: '/last-run',
      handler: async (req, res) => {
        if (JOB_ID === undefined) {
          res.json({ status: 'noJob' });
          return;
        }

        let listed: VisibleRunPage;
        try {
          // completed_only includes failures, so page until the newest success is in hand: a streak
          // of recent failures must not hide an older successful run.
          listed = await retryRead(() =>
            collectVisibleRuns(
              req,
              {
                completed_only: true,
                expand_tasks: true,
                limit: LAST_RUN_PAGE_SIZE,
                page_token: nonEmptyString(req.query.cursor),
              },
              (visible) => visible.some(isSuccessfulRun)
            )
          );
        } catch (err) {
          report('Designer request failed: %O', err);
          res.json({
            status: 'unavailable',
            reason: `Could not read this app's run history: ${errorMessage(err)}`,
          });
          return;
        }

        let active;
        try {
          // Trust active_only instead of duplicating Jobs lifecycle-state logic. Not retried: this
          // best-effort signal must not delay primary content.
          const activeRun = selectActiveRun(
            (
              await collectVisibleRuns(
                req,
                {
                  active_only: true,
                  expand_tasks: true,
                  limit: LAST_RUN_PAGE_SIZE,
                },
                (visible) => visible.length > 0
              )
            ).runs
          );
          const activeSummary = activeRun === undefined ? undefined : summarizeLastRun(activeRun);
          if (activeRun !== undefined && activeSummary !== undefined) {
            const lifeCycleState = lifeCycleStateOf(activeRun);
            active = {
              run: activeSummary,
              ...runParameterData(activeRun),
              ...(lifeCycleState === undefined ? {} : { lifeCycleState }),
            };
          }
        } catch (err) {
          report('Designer request failed: %O', err);
        }

        const run = selectLastSuccessfulRun(listed.runs);
        const summary = run === undefined ? undefined : summarizeLastRun(run);
        if (run === undefined || summary === undefined) {
          res.json({
            status: listed.nextPageToken === undefined ? 'none' : 'searching',
            nextPageToken: listed.nextPageToken,
            ...(active === undefined ? {} : { active }),
          });
          return;
        }
        summary.resultState = resultStateOf(run);
        res.json({
          status: 'found',
          run: summary,
          ...runParameterData(run),
          ...(active === undefined ? {} : { active }),
          result: await readRunResult(summary.taskRunId),
        });
      },
    });

    route({
      name: 'run',
      method: 'post',
      path: '/run',
      handler: async (req, res) => {
        try {
          const manifest = await loadManifest(true);
          if (manifest === undefined) {
            res.status(409).json({
              error: 'This app has no published configuration, so it cannot run.',
            });
            return;
          }
          if (JOB_ID === undefined) {
            res.status(409).json({
              error: 'This app is not connected to a job yet, so it cannot run.',
            });
            return;
          }
          if (!APP_ID) {
            res.status(409).json({
              error: 'This app has no runtime App ID, so it cannot attribute Job runs.',
            });
            return;
          }
          if (!isPublishedRunner(manifest.runner, await readJob())) {
            res.status(409).json({ error: APP_UPDATING_MESSAGE });
            return;
          }
          const attribution = await runAttribution(req, APP_ID, async (token) =>
            createWorkspaceClient({
              host: await wsClient().getHost(),
              token,
            }).currentUser.me({})
          );
          const userName = attribution?._lb_app_user_email;
          if (!attribution || !userName) {
            res.status(401).json({
              error: 'Sign in through Databricks Apps to run this app.',
            });
            return;
          }
          const submitted = isRecord(req.body) && isRecord(req.body.params) ? req.body.params : {};
          const resolved = await resolveRunParameters(
            manifest,
            submitted,
            requestViewer(req),
            appKitUploadStore(manifest.storage)
          );
          if (!resolved.ok) {
            res.status(400).json({
              error: resolved.error,
              ...(resolved.code ? { code: resolved.code } : {}),
            });
            return;
          }

          // The SDK can retry transient responses. Reuse the submission ID so those attempts
          // cannot start duplicate compute; the browser does not replay submissions.
          resolved.params[APP_REVISION_PARAM] = manifestRevision(manifest);
          const run = await wsClient().jobs.runNow({
            jobId: BigInt(JOB_ID),
            idempotencyToken: attribution._lb_app_submission_id,
            jobParameters: { ...resolved.params, ...attribution },
          });
          const jobRunId = idString(run?.runId);
          if (jobRunId === undefined) {
            res.status(502).json({
              error: 'The platform accepted the request but returned no run id.',
            });
            return;
          }
          res.json({ jobRunId });
        } catch (err) {
          report('Designer request failed: %O', err);
          res.status(502).json({ error: `Could not start the run: ${errorMessage(err)}` });
        }
      },
    });

    route({
      name: 'runStatus',
      method: 'get',
      path: '/run/:jobRunId',
      handler: async (req, res) => {
        const found = await readViewerRun(req, res);
        if (found === undefined) return;
        const { jobRunId, run } = found;

        const lifeCycleState = lifeCycleStateOf(run);
        const resultState = resultStateOf(run);
        // A run carrying a result_state has finished even if its lifecycle value is absent or one
        // this list does not know yet, so treat that as terminal rather than polling it forever.
        const terminal =
          (lifeCycleState != null && TERMINAL_LIFE_CYCLE_STATES.has(lifeCycleState)) || resultState != null;
        const snapshot = {
          jobRunId,
          taskRunId: summarizeLastRun(run)?.taskRunId,
          lifeCycleState,
          resultState,
          stateMessage: isRecord(run.state) ? nonEmptyString(run.state.state_message) : undefined,
          setupDurationMs: run.setup_duration,
          executionDurationMs: run.execution_duration,
          runPageUrl: run.run_page_url,
          terminal,
          ...runParameterData(run),
        };

        if (!terminal) {
          res.json(snapshot);
          return;
        }

        const failed = resultState === undefined || !SUCCESSFUL_RESULT_STATES.has(resultState);
        res.json({
          ...snapshot,
          result: await readRunResult(snapshot.taskRunId, failed),
        });
      },
    });

    route({
      name: 'cancelRun',
      method: 'delete',
      path: '/run/:jobRunId',
      handler: async (req, res) => {
        const found = await readViewerRun(req, res);
        if (found === undefined) return;
        try {
          // Polling settles cancellation from the run's own state.
          await wsClient().jobs.cancelRun({ runId: BigInt(found.jobRunId) });
          res.json({ cancelled: true });
        } catch (err) {
          report('Designer request failed: %O', err);
          res.status(502).json({
            error: `Could not cancel run ${found.jobRunId}: ${errorMessage(err)}`,
          });
        }
      },
    });

    route({
      name: 'runs',
      method: 'get',
      path: '/runs',
      handler: async (req, res) => {
        if (JOB_ID === undefined) {
          res.json({ status: 'noJob' });
          return;
        }
        const windowSize = resolveHistoryWindow(req.query?.window);

        let history: VisibleRunPage;
        try {
          history = await retryRead(() =>
            collectVisibleRuns(
              req,
              {
                completed_only: true,
                limit: RUN_HISTORY_PAGE_SIZE,
                page_token: nonEmptyString(req.query.cursor),
              },
              (visible) => visible.length >= windowSize
            )
          );
        } catch (err) {
          report('Designer request failed: %O', err);
          res.json({
            status: 'unavailable',
            reason: `Could not read this app's run history: ${errorMessage(err)}`,
          });
          return;
        }

        const page = summarizeRunHistory(history);
        res.json({
          status: 'found',
          runs: page.entries,
          hasMore: page.hasMore,
          nextPageToken: page.nextPageToken,
          window: windowSize,
        });
      },
    });
  }
  return {
    registerRoutes,
    close() {
      cachedManifest = undefined;
      cachedManifestFolder = undefined;
      completedTaskOutputs.clear();
    },
  };
}

export function parseStorageFileSize(contentLength: unknown): number | undefined {
  const size = Number(contentLength);
  return Number.isSafeInteger(size) && size >= 0 ? size : undefined;
}

import type { WorkspaceClient } from './workspaceClient';
import { fileSize, isMissingFile, readUploadRecord, uploadBytes } from './workspaceFiles';
import type { AppStorage } from '../shared/storageConfig';
import { UPLOAD_UNAVAILABLE, UPLOAD_UNAVAILABLE_MESSAGE } from '../shared/storageConfig';
import { uploadStoragePath } from '../shared/storageConfig';
import { UploadError, type UploadStore } from './fileUploads';

export function createUploadStore(client: WorkspaceClient, config: AppStorage | undefined): UploadStore {
  const access = async <T>(path: string, operation: () => Promise<T>): Promise<T> => {
    try {
      if (!config) throw new UploadError(409, 'File uploads are not configured.');
      if (!path.startsWith(`${uploadStoragePath(config)}/`)) throw new Error('Invalid upload storage destination.');
      return await operation();
    } catch (error) {
      if (error instanceof UploadError) throw error;
      const missing = isMissingFile(error);
      throw new UploadError(
        missing ? 404 : 502,
        missing
          ? UPLOAD_UNAVAILABLE_MESSAGE
          : 'Could not access upload storage. Check the app volume resource and permissions.',
        { cause: error, ...(missing ? { code: UPLOAD_UNAVAILABLE } : {}) }
      );
    }
  };
  return {
    mkdir: (path) =>
      access(path, async () => {
        await client.files.createDirectory({ directoryPath: path });
      }),
    put: (path, bytes) => access(path, () => uploadBytes(client, path, bytes)),
    putStream: (path, stream) =>
      access(path, async () => {
        await client.files.uploadFile({ filePath: path, contents: stream, overwrite: false });
      }),
    read: (path) =>
      access(path, async () => {
        const contents = await readUploadRecord(client, path);
        try {
          const record: unknown = JSON.parse(contents);
          return record;
        } catch {
          throw new UploadError(409, 'The upload record is unreadable.');
        }
      }),
    download: (path) =>
      access(path, async () => {
        const result = await client.files.downloadFile({ filePath: path });
        if (!result.contents) throw new UploadError(502, 'The uploaded file has no readable contents.');
        return result.contents;
      }),
    size: (path) =>
      access(path, async () => {
        return fileSize(client, path);
      }),
    delete: (path) =>
      access(path, async () => {
        await client.files.deleteFile({ filePath: path });
      }),
  };
}

import { Readable } from 'node:stream';

import type { IAppRequest as Request, IAppResponse as Response } from '@databricks/appkit/dist/shared/src/plugin';
import type { RouteConfig } from '@databricks/appkit/dist/shared/src/plugin';

import { validateFileFormat } from '../shared/fileFormats';
import { MAX_UPLOAD_SIZE_LABEL, UPLOAD_REFERENCE, UPLOAD_UNAVAILABLE, type AppStorage } from '../shared/storageConfig';
import { streamFileDownload } from './fileDownloads';
import { UploadError, resolveUpload, saveUploadStream, type UploadStore } from './fileUploads';

interface UploadManifest {
  storage?: AppStorage;
  parameters: { name: string; type: string; fileFormats?: string[] }[];
}

interface UploadDependencies {
  manifest(): Promise<UploadManifest | undefined>;
  viewer(req: Request): string | undefined;
  store(storage: AppStorage): UploadStore;
  report: (error: unknown) => void;
}

const fileParameter = (manifest: UploadManifest | undefined, name: string) =>
  manifest?.parameters.find((parameter) => parameter.name === name && parameter.type === 'file');

function sendUploadError(res: Response, error: unknown, fallback: string) {
  res
    .status(error instanceof UploadError ? error.status : 502)
    .json(
      error instanceof UploadError
        ? { ...(error.code ? { code: error.code } : {}), error: error.message }
        : { error: fallback }
    );
}

export function registerUploadRoutes(route: (config: RouteConfig) => void, deps: UploadDependencies) {
  let activeUploads = 0;

  route({
    name: 'downloadUpload',
    method: 'get',
    path: '/uploads/:parameterName/:reference/download',
    handler: async (req, res) => {
      res.setHeader('Cache-Control', 'no-store');
      try {
        if (req.method !== 'GET') throw new UploadError(405, 'Use GET to download the file.');
        if (req.get('range'))
          throw new UploadError(416, 'Partial downloads are not supported. Retry the full download.');
        const viewer = deps.viewer(req);
        if (!viewer) throw new UploadError(401, 'Sign in through Databricks Apps to download files.');
        const manifest = await deps.manifest();
        const parameter = fileParameter(manifest, req.params.parameterName);
        if (!parameter || !manifest?.storage) {
          throw new UploadError(404, 'This file parameter is no longer available. Review the app inputs.', {
            code: UPLOAD_UNAVAILABLE,
          });
        }
        const reference = String(req.params.reference);
        if (!UPLOAD_REFERENCE.test(reference)) throw new UploadError(400, 'The upload reference is invalid.');
        const store = deps.store(manifest.storage);
        const { path, upload } = await resolveUpload(store, manifest.storage, viewer, parameter.name, reference);
        await streamFileDownload(res, await store.download(path), upload.filename, upload.size, deps.report);
      } catch (error) {
        if (!(error instanceof UploadError)) deps.report(error);
        if (res.headersSent) {
          res.destroy(error instanceof Error ? error : undefined);
        } else {
          sendUploadError(
            res,
            error,
            'Could not download the uploaded file. Check the app volume resource and permissions.'
          );
        }
      }
    },
  });

  route({
    name: 'upload',
    method: 'post',
    path: '/uploads/:parameterName',
    skipBodyParsing: true,
    handler: async (req, res) => {
      let admitted = false;
      try {
        const manifest = await deps.manifest();
        const parameter = fileParameter(manifest, req.params.parameterName);
        if (!parameter || !manifest?.storage) {
          res.status(404).json({
            error: 'This file parameter is no longer available. Review the app inputs.',
            code: UPLOAD_UNAVAILABLE,
          });
          return;
        }
        const viewer = deps.viewer(req);
        if (!viewer) {
          res.status(401).json({
            error: 'Sign in through Databricks Apps to upload files.',
          });
          return;
        }
        const store = deps.store(manifest.storage);
        if (req.get('content-type') !== 'application/octet-stream')
          throw new UploadError(415, 'Upload the file as an octet stream.');
        if (activeUploads >= 4) throw new UploadError(429, 'Uploads are busy. Try again shortly.');
        const contentLength = req.get('content-length');
        if (contentLength !== undefined && !/^\d+$/.test(contentLength))
          throw new UploadError(400, 'The Content-Length header is invalid.');
        const declaredSize = contentLength === undefined ? undefined : Number(contentLength);
        if (declaredSize !== undefined && declaredSize > manifest.storage.maxUploadFileSizeBytes)
          throw new UploadError(413, `The file exceeds the ${MAX_UPLOAD_SIZE_LABEL} upload limit.`);
        let filename: string;
        try {
          filename = decodeURIComponent(req.get('x-file-name') ?? '');
        } catch {
          throw new UploadError(400, 'The filename is invalid.');
        }
        const formatError = validateFileFormat(filename, parameter.fileFormats);
        if (formatError) throw new UploadError(400, formatError);
        activeUploads += 1;
        admitted = true;
        res.status(201).json({
          upload: await saveUploadStream(
            store,
            manifest.storage,
            viewer,
            parameter.name,
            filename,
            Readable.toWeb(req) as ReadableStream<Uint8Array>,
            declaredSize
          ),
        });
      } catch (error) {
        req.resume();
        sendUploadError(res, error, 'Could not store the upload. Check the app volume resource and permissions.');
      } finally {
        if (admitted) activeUploads -= 1;
      }
    },
  });
}

import type { createWorkspaceClient } from '@databricks/appkit';

// SDK 0.89's root WorkspaceClient alias is broken; the public factory retains its complete type.
export type WorkspaceClient = ReturnType<typeof createWorkspaceClient>;

import type { WorkspaceClient } from './workspaceClient';
import { isRecord } from '../shared/values';
import { parseStorageFileSize } from './storageVolume';

function fileApiPath(path: string): string {
  return `/api/2.0/fs/files${path.split('/').map(encodeURIComponent).join('/')}`;
}

export function isMissingFile(error: unknown): boolean {
  // Raw requests and typed Files methods expose different SDK error shapes.
  return isRecord(error) && (error.statusCode === 404 || error.httpStatusCode === 404);
}

export async function fileSize(client: WorkspaceClient, path: string): Promise<number | undefined> {
  // The typed getFileMetadata method drops HEAD response headers in SDK 0.89.
  const response = await client.request({ method: 'HEAD', path: fileApiPath(path) });
  return parseStorageFileSize(response.headers.get('content-length') ?? undefined);
}

export async function uploadBytes(client: WorkspaceClient, path: string, bytes: Uint8Array): Promise<void> {
  // In-memory records need Content-Length and a replayable body for transport retries.
  const response = await client.request({
    method: 'PUT',
    path: fileApiPath(path),
    query: { overwrite: 'false' },
    headers: new Headers({ 'Content-Type': 'application/octet-stream' }),
    body: new Uint8Array(bytes),
  });
  await response.body?.cancel();
}

export async function readUploadRecord(client: WorkspaceClient, path: string): Promise<string> {
  const { contents } = await client.files.downloadFile({ filePath: path });
  if (!contents) throw new Error('The upload record has no readable contents.');
  const reader = contents.getReader();
  const decoder = new TextDecoder();
  let bytesRead = 0;
  let text = '';
  try {
    for (;;) {
      const next = await reader.read();
      if (next.done) break;
      const chunk: unknown = next.value;
      if (!(chunk instanceof Uint8Array)) throw new Error('The upload record did not contain bytes.');
      bytesRead += chunk.byteLength;
      if (bytesRead > 16 * 1024) throw new Error('The upload record exceeds 16 KiB.');
      text += decoder.decode(chunk, { stream: true });
    }
    return text + decoder.decode();
  } finally {
    try {
      await reader.cancel();
    } finally {
      reader.releaseLock();
    }
  }
}

import { z } from 'zod/mini';

import { isFileFormats } from './fileFormats.ts';
import { hasInvalidFileOutputDeclaration, parseFileOutput } from './fileOutputs.ts';
import { isValidMultiselectConfig } from './multiselect.ts';
import { RUNNER_REVISION_PARAM } from './publishedRunner.ts';
import { parseAppStorage } from './storageConfig.ts';

const nonEmptyString = z.string().check(z.minLength(1));
const stringOrEmpty = z.catch(z.string(), '');
const record = z.record(z.string(), z.unknown());
const optionalBoolean = z.catch(z.optional(z.boolean()), undefined);

const RESERVED_PARAMETERS = new Set(['target_node', 'ld_display_outputs', 'ld_display_outputs_for']);

export function isReservedParameter(name: string): boolean {
  return RESERVED_PARAMETERS.has(name) || name.startsWith('_lb_');
}

const chartSpecSchema = z.looseObject({ widgetType: nonEmptyString });
const provenanceSchema = z.object({
  publishedAt: z.number().check(z.positive()),
  generatorVersion: z.catch(z.optional(z.union([z.string(), z.number()])), undefined),
});
const targetSchema = z.object({ nodeId: nonEmptyString, label: stringOrEmpty });
const runnerSchema = z
  .object({
    revision: z.string().check(z.regex(/^[0-9a-f]{64}$/)),
    parameters: z.record(z.string(), z.string()),
  })
  .check(z.refine((runner) => runner.parameters[RUNNER_REVISION_PARAM] === runner.revision));

const parameterSchema = z.pipe(
  z.object({
    name: nonEmptyString.check(z.refine((name) => !isReservedParameter(name))),
    label: z.string(),
    type: z.catch(z.enum(['text', 'number', 'dropdown', 'combobox', 'multiselect', 'file']), 'text'),
    defaultValue: stringOrEmpty,
    choices: z.catch(z.optional(z.array(z.string())), undefined),
    fileFormats: z.optional(z.unknown()),
    help: z.optional(z.unknown()),
  }),
  z.transform((entry) => {
    const choices = entry.type === 'combobox' || (entry.choices?.length ?? 0) > 0 ? entry.choices : undefined;
    const type = entry.type === 'dropdown' && choices === undefined ? 'text' : entry.type;
    return {
      name: entry.name,
      label: entry.label,
      type,
      defaultValue: type === 'file' ? '' : entry.defaultValue,
      ...((type === 'dropdown' || type === 'combobox' || type === 'multiselect') && choices !== undefined
        ? { choices }
        : {}),
      ...(type === 'file' && isFileFormats(entry.fileFormats) ? { fileFormats: entry.fileFormats } : {}),
      ...(typeof entry.help === 'string' && entry.help !== '' ? { help: entry.help } : {}),
    };
  })
);

const markdownBlockSchema = z.pipe(
  z.object({
    type: z.literal('markdown'),
    id: z.catch(z.optional(nonEmptyString), undefined),
    text: z.string(),
    hideUntilResults: optionalBoolean,
  }),
  z.transform(({ type, id, text, hideUntilResults }) => ({
    type,
    ...(id === undefined ? {} : { id }),
    text,
    ...(hideUntilResults === undefined ? {} : { hideUntilResults }),
  }))
);

const outputBlockSchema = z.pipe(
  z
    .object({
      type: z.literal('output'),
      id: nonEmptyString,
      label: stringOrEmpty,
      nodeId: stringOrEmpty,
      port: z.optional(nonEmptyString),
      kind: z.optional(z.literal('html')),
      chartSpec: z.catch(z.optional(chartSpecSchema), undefined),
      hideUntilResults: optionalBoolean,
      fileOutput: z.optional(z.transform(parseFileOutput)),
      disabled: optionalBoolean,
      parentGroupId: z.catch(z.optional(nonEmptyString), undefined),
    })
    .check(
      z.refine((block) =>
        block.kind === 'html'
          ? block.port === undefined && block.chartSpec === undefined && block.fileOutput === undefined
          : block.port !== undefined
      )
    ),
  z.transform(({ chartSpec, fileOutput, hideUntilResults, disabled, parentGroupId, ...block }) => ({
    ...block,
    ...(chartSpec === undefined ? {} : { chartSpec }),
    ...(fileOutput === undefined ? {} : { fileOutput }),
    ...(hideUntilResults === undefined ? {} : { hideUntilResults }),
    ...(disabled === undefined ? {} : { disabled }),
    ...(parentGroupId === undefined ? {} : { parentGroupId }),
  }))
);

const blockSchema = z.union([markdownBlockSchema, outputBlockSchema]);

function parseBlocks(raw: unknown): AppManifestBlock[] {
  const seen = new Set<string>();
  return (Array.isArray(raw) ? raw : []).flatMap((entry) => {
    const block = blockSchema.safeParse(entry).data;
    if (!block) return [];
    if (block.type === 'output') {
      if (seen.has(block.id)) return [];
      seen.add(block.id);
    }
    return [block];
  });
}

// Both the workspace manifest and /config response use this contract. Ordinary malformed display
// entries can be omitted; declarations governing file access must reject the entire manifest.
export const appManifestSchema = z.pipe(
  z.object({
    version: z.literal(8),
    runner: z.optional(runnerSchema),
    appName: nonEmptyString,
    subtitle: z.optional(z.unknown()),
    provenance: z.optional(z.unknown()),
    target: z.optional(z.unknown()),
    storage: z.optional(z.unknown()),
    blocks: z.unknown(),
    parameters: z.array(z.unknown()),
  }),
  z.transform((raw, ctx) => {
    const storage = parseAppStorage(raw.storage);
    const blocks = parseBlocks(raw.blocks);
    const entries = raw.parameters.flatMap((entry) => {
      const parsed = record.safeParse(entry).data;
      return parsed ? [parsed] : [];
    });
    if (
      !blocks.some((block) => block.type === 'output') ||
      hasInvalidFileOutputDeclaration(raw.blocks) ||
      (raw.storage !== undefined && !storage) ||
      entries.some(
        (entry) =>
          (entry.type === 'file' &&
            (!storage || (entry.fileFormats !== undefined && !isFileFormats(entry.fileFormats)))) ||
          (entry.type === 'multiselect' && !isValidMultiselectConfig(entry.choices, entry.defaultValue))
      )
    ) {
      ctx.issues.push({
        code: 'custom',
        input: raw,
        message: 'Invalid published app configuration',
      });
      return z.NEVER;
    }
    const provenance = provenanceSchema.safeParse(raw.provenance).data;
    const target = targetSchema.safeParse(raw.target).data;
    return {
      ...(storage === undefined ? {} : { storage }),
      ...(raw.runner === undefined ? {} : { runner: raw.runner }),
      version: raw.version,
      appName: raw.appName,
      ...(typeof raw.subtitle === 'string' && raw.subtitle !== '' ? { subtitle: raw.subtitle } : {}),
      ...(provenance === undefined ? {} : { provenance }),
      ...(target === undefined ? {} : { target }),
      blocks,
      parameters: entries.flatMap((entry) => {
        const parameter = parameterSchema.safeParse(entry).data;
        return parameter ? [parameter] : [];
      }),
    };
  })
);

export type AppChartSpec = z.output<typeof chartSpecSchema>;
export type AppParameter = z.output<typeof parameterSchema>;
export type AppMarkdownBlock = z.output<typeof markdownBlockSchema>;
export type AppOutputBlock = z.output<typeof outputBlockSchema>;
export type AppManifestBlock = z.output<typeof blockSchema>;
export type AppManifest = z.output<typeof appManifestSchema>;

export const outputBlockTitle = ({ label, nodeId, id }: Pick<AppOutputBlock, 'label' | 'nodeId' | 'id'>): string =>
  label !== '' ? label : nodeId !== '' ? nodeId : id;

const FORMAT_EXTENSIONS: Record<string, readonly string[]> = {
  excel: ['.xls', '.xlsx'],
  csv: ['.csv', '.tsv', '.tab', '.txt'],
  json: ['.json', '.jsonl', '.ndjson'],
  parquet: ['.parquet'],
  avro: ['.avro'],
  orc: ['.orc'],
  xml: ['.xml'],
  pdf: ['.pdf'],
};
const COMPRESSION_EXTENSIONS = ['.gz', '.bz2', '.deflate', '.lz4', '.snappy', '.zst', '.zstd'];

export const isFileFormats = (value: unknown): value is string[] =>
  Array.isArray(value) &&
  value.every((format) => typeof format === 'string' && format !== '' && format === format.trim().toLowerCase());

function extensionsFor(format: string): readonly string[] | undefined {
  const extensions = Object.hasOwn(FORMAT_EXTENSIONS, format) ? FORMAT_EXTENSIONS[format] : undefined;
  if (!extensions || !['csv', 'json', 'xml'].includes(format)) return extensions;
  return extensions.flatMap((extension) => [extension, ...COMPRESSION_EXTENSIONS.map((suffix) => extension + suffix)]);
}

// Text, binary, inferred and runtime-parameterized formats have no reliable filename restriction.
export function uploadAccept(fileFormats: readonly string[] = []): string | undefined {
  const restrictions = fileFormats.flatMap((format) => {
    const extensions = extensionsFor(format);
    return extensions ? [extensions] : [];
  });
  return (
    restrictions[0]?.filter((extension) => restrictions.every((allowed) => allowed.includes(extension))).join(',') ||
    undefined
  );
}

export function validateFileFormat(filename: string, fileFormats: readonly string[] = []): string | undefined {
  for (const format of fileFormats) {
    const extensions = extensionsFor(format);
    if (extensions && !extensions.some((extension) => filename.toLowerCase().endsWith(extension))) {
      const label = format === 'excel' ? 'Excel' : format.toUpperCase();
      return `This Source expects ${label} (${FORMAT_EXTENSIONS[format].join(', ')}). Choose a matching file.`;
    }
  }
  return undefined;
}

import { isVolumeName } from './storageConfig.ts';
import { isRecord } from './values.ts';

export const FILE_OUTPUTS_PARAM = '_lb_file_outputs';
export const OUTPUT_NAMESPACE_PARAM = '_lb_output_namespace';
export const APP_REVISION_PARAM = '_lb_app_revision';
export const FILE_OUTPUTS_MIME_TYPE = 'application/vnd.databricks.lakeflow-designer.files+json';
export const MAX_OUTPUT_FILES = 50;

export interface FileOutputConfig {
  volumes: string[];
}
export interface WrittenFile {
  path: string;
}
export type FileOutputBehavior = 'run_artifact' | 'shared_append' | 'shared_workbook_update';

export function parseFileOutputBehavior(value: unknown): FileOutputBehavior | undefined {
  return value === 'run_artifact' || value === 'shared_append' || value === 'shared_workbook_update'
    ? value
    : undefined;
}

export interface WrittenFiles {
  node: string;
  files: WrittenFile[];
  // Older receipts omit this; never infer run isolation from a path or the current manifest.
  behavior?: FileOutputBehavior;
}

export function parseFileOutput(value: unknown): FileOutputConfig | undefined {
  if (
    typeof value !== 'object' ||
    value === null ||
    !('volumes' in value) ||
    !Array.isArray(value.volumes) ||
    value.volumes.length === 0 ||
    value.volumes.length > 50
  ) {
    return undefined;
  }
  if (!value.volumes.every((volume): volume is string => typeof volume === 'string' && isVolumeName(volume))) {
    return undefined;
  }
  return { volumes: [...new Set(value.volumes)].sort() };
}

export function hasInvalidFileOutputDeclaration(blocks: unknown): boolean {
  if (!Array.isArray(blocks)) return false;
  const records = blocks.filter(isRecord);
  const outputIds = records.filter((block) => block.type === 'output').map((block) => block.id);
  // Preview blocks may be omitted when malformed. File blocks must fail closed instead:
  // dropping one could remove the ownership/policy controls while the runner still writes it.
  return records.some(
    (block) =>
      block.fileOutput !== undefined &&
      (block.type !== 'output' ||
        typeof block.id !== 'string' ||
        block.id.trim() === '' ||
        typeof block.nodeId !== 'string' ||
        block.nodeId.trim() === '' ||
        outputIds.filter((id) => id === block.id).length !== 1 ||
        parseFileOutput(block.fileOutput) === undefined)
  );
}

// Require literal, canonical paths. Never normalize an untrusted path into the approved scope.
export function isOutputFilePath(path: unknown, config: FileOutputConfig): path is string {
  if (
    typeof path !== 'string' ||
    path.length > 4096 ||
    [...path].some((character) => character === '\\' || character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127)
  )
    return false;
  const root = config.volumes
    .map((volume) => `/Volumes/${volume.replaceAll('.', '/')}/`)
    .find((root) => path.startsWith(root));
  if (!root) return false;
  const segments = path.slice(root.length).split('/');
  return (
    segments.every((segment) => segment !== '' && segment !== '.' && segment !== '..') &&
    /\.(csv|json|xlsx)$/i.test(segments.at(-1) ?? '')
  );
}

export const fileDownloadRoute = (runId: string, outputId: string, index: number) =>
  `/api/designer/run/${encodeURIComponent(runId)}/files/${encodeURIComponent(outputId)}/${index}/download`;

import { isRecord, nonEmptyString } from './values.ts';

export interface GuardrailDiagnostic {
  nodeId?: string;
  operatorName: string;
  checkIndex: number;
  checkType?: string;
  severity: 'warning' | 'failure';
  message: string;
}

export interface RunDiagnostics {
  diagnostics?: GuardrailDiagnostic[];
  failureReason?: string;
}

export function parseRunDiagnostics(raw: { diagnostics?: unknown; failureReason?: unknown }): RunDiagnostics {
  const diagnostics = Array.isArray(raw.diagnostics)
    ? raw.diagnostics.flatMap((entry): GuardrailDiagnostic[] => {
        if (!isRecord(entry)) return [];
        const operatorName = nonEmptyString(entry.operatorName);
        const message = nonEmptyString(entry.message);
        const nodeId = nonEmptyString(entry.nodeId);
        const checkType = nonEmptyString(entry.checkType);
        if (
          !operatorName ||
          !message ||
          typeof entry.checkIndex !== 'number' ||
          !Number.isSafeInteger(entry.checkIndex) ||
          entry.checkIndex < 0 ||
          (entry.severity !== 'warning' && entry.severity !== 'failure')
        )
          return [];
        return [
          {
            operatorName,
            checkIndex: entry.checkIndex,
            severity: entry.severity,
            message,
            ...(nodeId ? { nodeId } : {}),
            ...(checkType ? { checkType } : {}),
          },
        ];
      })
    : [];
  const failureReason = nonEmptyString(raw.failureReason);
  return {
    ...(diagnostics.length > 0 ? { diagnostics } : {}),
    ...(failureReason ? { failureReason } : {}),
  };
}

export const MAX_HTML_OUTPUT_CHARS = 4 * 1024 * 1024;

export function isHtmlOutput(value: unknown): value is string {
  return typeof value === 'string' && value.length <= MAX_HTML_OUTPUT_CHARS;
}

const MULTISELECT_DELIMITER = ',';

export function parseMultiselectValue(value: string): string[] {
  return value === '' ? [] : value.split(MULTISELECT_DELIMITER);
}

export function isValidMultiselectValue(value: unknown, choices: readonly string[]): value is string {
  return typeof value === 'string' && parseMultiselectValue(value).every((choice) => choices.includes(choice));
}

export function isValidMultiselectConfig(choices: unknown, defaultValue: unknown): boolean {
  return (
    Array.isArray(choices) &&
    choices.length > 0 &&
    choices.every(
      (choice): choice is string =>
        typeof choice === 'string' && choice !== '' && !choice.includes(MULTISELECT_DELIMITER)
    ) &&
    isValidMultiselectValue(defaultValue === undefined ? '' : defaultValue, choices)
  );
}

export function toggleMultiselectValue(value: string, choice: string, selected: boolean): string {
  const selections = new Set(parseMultiselectValue(value));
  if (selected) selections.add(choice);
  else selections.delete(choice);
  return [...selections].join(MULTISELECT_DELIMITER);
}

import { isRecord } from './values.ts';

export const RUNNER_REVISION_PARAM = '_lb_runner_revision';
export const APP_UPDATING_MESSAGE =
  'This App is updating. New runs are paused until publication finishes. Try again shortly.';

export interface PublishedRunner {
  revision: string;
  parameters: Record<string, string>;
}

export function isPublishedRunner(runner: PublishedRunner | undefined, job: unknown): boolean {
  if (!runner || !isRecord(job) || !isRecord(job.settings) || !Array.isArray(job.settings.tasks)) return false;
  if (job.settings.tasks.length !== 1) return false;
  const task: unknown = job.settings.tasks[0];
  if (!isRecord(task) || !isRecord(task.notebook_task)) return false;
  const notebook = task.notebook_task;
  const parameters = notebook.base_parameters;
  return (
    typeof notebook.notebook_path === 'string' &&
    notebook.notebook_path.endsWith(`/runner-${runner.revision}.designer.py`) &&
    isRecord(parameters) &&
    Object.keys(parameters).length === Object.keys(runner.parameters).length &&
    Object.entries(runner.parameters).every(([name, value]) => parameters[name] === value)
  );
}

export const DISPLAY_ROW_LIMIT = 1000;

export interface ResultPreview {
  // null means the source did not report whether its result was truncated.
  truncated: boolean | null;
  total_row_count?: number;
}

export function summarizeResultPreview(
  receivedRowCount: number,
  truncated: unknown,
  totalRowCount?: unknown
): ResultPreview {
  const validTotal =
    typeof totalRowCount === 'number' &&
    Number.isSafeInteger(totalRowCount) &&
    totalRowCount >= receivedRowCount &&
    (truncated !== true || totalRowCount > receivedRowCount);
  // Only a positively complete source result lets us use its length as an exact total.
  const total = validTotal ? totalRowCount : truncated === false ? receivedRowCount : undefined;
  const hasMoreRows =
    truncated === true || receivedRowCount > DISPLAY_ROW_LIMIT || (total !== undefined && total > receivedRowCount);
  return {
    truncated: hasMoreRows ? true : truncated === false || total !== undefined ? false : null,
    ...(total === undefined ? {} : { total_row_count: total }),
  };
}

export interface AppStorage {
  volume: string;
  path: string;
  maxUploadFileSizeBytes: number;
}

export const MAX_UPLOAD_BYTES = 5 * 1024 * 1024 * 1024;
export const MAX_UPLOAD_SIZE_LABEL = '5 GB';
export const UPLOAD_UNAVAILABLE = 'UPLOAD_UNAVAILABLE';
export const UPLOAD_UNAVAILABLE_MESSAGE = 'This upload is no longer available. Upload the file again.';
export const UPLOAD_REFERENCE = /^upload:([0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/;

export const uploadStoragePath = (storage: AppStorage): string => `${storage.path}/uploads`;

const SAFE_NAME = /^[A-Za-z0-9_-]+$/;

export function isVolumeName(volume: string): boolean {
  const names = volume.split('.');
  return names.length === 3 && names.every((name) => SAFE_NAME.test(name));
}

export function parseAppStorage(value: unknown): AppStorage | undefined {
  if (
    typeof value !== 'object' ||
    value === null ||
    !('volume' in value) ||
    !('path' in value) ||
    !('maxUploadFileSizeBytes' in value)
  )
    return undefined;
  if (typeof value.volume !== 'string' || typeof value.path !== 'string' || !isVolumeName(value.volume))
    return undefined;
  const prefix = `/Volumes/${value.volume.replaceAll('.', '/')}/designer_apps/`;
  if (!value.path.startsWith(prefix) || !SAFE_NAME.test(value.path.slice(prefix.length))) return undefined;
  if (
    typeof value.maxUploadFileSizeBytes !== 'number' ||
    !Number.isSafeInteger(value.maxUploadFileSizeBytes) ||
    value.maxUploadFileSizeBytes <= 0 ||
    value.maxUploadFileSizeBytes > MAX_UPLOAD_BYTES
  )
    return undefined;
  return {
    volume: value.volume,
    path: value.path,
    maxUploadFileSizeBytes: value.maxUploadFileSizeBytes,
  };
}

export const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

export const nonEmptyString = (value: unknown): string | undefined =>
  typeof value === 'string' && value !== '' ? value : undefined;

export const positiveInt = (value: unknown): number | undefined => {
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : undefined;
};

// Run and job IDs are int64: keep them as decimal strings, since Number corrupts values past 2^53-1.
export const idString = (value: unknown): string | undefined => {
  if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'bigint') {
    return undefined;
  }
  const text = String(value);
  return /^[1-9][0-9]*$/.test(text) ? text : undefined;
};

export const stringValues = (value: unknown): Record<string, string> | undefined =>
  isRecord(value)
    ? Object.fromEntries(
        Object.entries(value).filter((entry): entry is [string, string] => typeof entry[1] === 'string')
      )
    : undefined;

export const errorMessage = (error: unknown): string => (error instanceof Error ? error.message : String(error));
